"use client"

import { CheckCircleIcon, QueueIcon, WarningOctagonIcon, SparkleIcon } from "@phosphor-icons/react"
import React, { useMemo } from "react"
import {
    motion,
    useReducedMotion,
} from "framer-motion"
import { useTranslations } from "next-intl"
import { cn } from "@heroui/react"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { WithClassNames } from "@/modules/types/base/class-name"
import { resolveAiProcessingCopy } from "@/components/utils/ai"

/** Props for {@link AIProcessingText}. */
export interface AIProcessingTextProps extends WithClassNames<{
    innerPanel?: string
    icon?: string
}> {
    jobCategory: JobCategory
    jobStatus: JobStatus
    error?: string
    showIcon?: boolean
}

const defaultIconClassName = "size-10 shrink-0"

/**
 * Theme CSS variable for border / spinner accent (aligns with status icon colors).
 */
const accentCssVarForStatus = (status: JobStatus): string => {
    switch (status) {
    case JobStatus.Queued:
    case JobStatus.Processing:
        return "var(--warning)"
    case JobStatus.Completed:
        return "var(--success)"
    case JobStatus.Failed:
        return "var(--danger)"
    default:
        return "var(--warning)"
    }
}

const useSpinningBorder = (status: JobStatus): boolean =>
    status === JobStatus.Queued 
|| status === JobStatus.Processing 
|| status === JobStatus.Completed
|| status === JobStatus.Failed

/**
 * Localized title + description for an AI job (from the `aiProcessing.*` locale namespace).
 * @param props - {@link AIProcessingTextProps}
 */
export const AIProcessingText = (props: AIProcessingTextProps) => {
    const {
        jobCategory,
        jobStatus,
        error,
        showIcon = true,
        classNames,
        className,
    } = props
    const t = useTranslations()
    const prefersReducedMotion = useReducedMotion()
    const accentVar = useMemo(
        () => accentCssVarForStatus(jobStatus),
        [
            jobStatus,
        ],
    )
    const spinningBorder = useSpinningBorder(jobStatus)
    const copy = useMemo(
        () => resolveAiProcessingCopy(
            t,
            {
                jobCategory,
                jobStatus,
                error,
            },
        ),
        [
            t,
            jobCategory,
            jobStatus,
            error,
        ],
    )
    const statusIcon = useMemo(() => {
        switch (jobStatus) {
        case JobStatus.Queued:
            return <QueueIcon className={cn(classNames?.icon, defaultIconClassName, "text-muted animate-pulse")} />
        case JobStatus.Processing:
            return <SparkleIcon className={cn(classNames?.icon, defaultIconClassName, "text-warning-soft-foreground animate-pulse")} />
        case JobStatus.Completed:
            return <CheckCircleIcon className={cn(classNames?.icon, defaultIconClassName, "text-success-soft-foreground")} />
        case JobStatus.Failed:
            return <WarningOctagonIcon className={cn(classNames?.icon, defaultIconClassName, "text-danger-soft-foreground")} />
        default:
            return null
        }
    }, [
        jobStatus,
        classNames?.icon,
    ])
    if (!copy) {
        return null
    }
    if (showIcon && !statusIcon) {
        return null
    }
    const textBlock = (
        <>
            <div className="text-sm font-medium text-foreground mb-1">{copy.title}</div>
            <div className="text-xs text-muted">{copy.description}</div>
            {jobStatus === JobStatus.Failed && copy.error && (
                <div className="mt-1 break-all text-xs text-danger-soft-foreground">{copy.error}</div>
            )}
        </>
    )
    const innerBody = !showIcon ? (
        <div className="w-full min-w-0 text-center">
            {textBlock}
        </div>
    ) : (
        <div className="flex w-full items-center gap-2">
            {statusIcon}
            <div className="w-full min-w-0">
                {textBlock}
            </div>
        </div>
    )

    if (spinningBorder) {
        return (
            <div className={cn("relative overflow-hidden rounded-2xl p-[2px]", className)}>
                <motion.div
                    className={cn(
                        "pointer-events-none absolute left-1/2 top-1/2 aspect-square h-[220%] min-h-[140%] w-[220%] min-w-[140%]",
                        "-translate-x-1/2 -translate-y-1/2",
                    )}
                    style={{
                        background: `conic-gradient(from 0deg, transparent 0deg, transparent 220deg, ${accentVar} 275deg, transparent 320deg)`,
                    }}
                    aria-hidden
                    animate={
                        prefersReducedMotion
                            ? {
                                rotate: 0,
                            }
                            : {
                                rotate: 360,
                            }
                    }
                    transition={
                        prefersReducedMotion
                            ? {
                                duration: 0,
                            }
                            : {
                                repeat: Infinity,
                                duration: 2.8,
                                ease: "linear",
                            }
                    }
                />
                <div className={cn("relative z-[1] rounded-[calc(1rem-2px)] bg-background p-3", classNames?.innerPanel)}>
                    {innerBody}
                </div>
            </div>
        )
    }
    return (
        <div
            className={
                cn(
                    "rounded-3xl border-2 border-solid bg-background p-3",
                    className,
                )
            }
            style={{
                borderColor: accentVar,
            }}
        >
            {innerBody}
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef } from "react"
import {
    Background,
    BackgroundVariant,
    ControlButton,
    Controls,
    type Node,
    type NodeMouseHandler,
    ReactFlow,
    useEdgesState,
    useNodesState,
    useReactFlow,
} from "@xyflow/react"
import { FrameCornersIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useTheme } from "next-themes"
import { build } from "../build"
import type { MindMapThemeMode } from "../build"
import { computeMindMapProgress, resolveContentHref } from "../progress"
import { useMindMapFitView } from "../hooks"
import { COURSE_MODULE_NODE_TYPE, CourseModuleNode } from "../ModuleNode"
import type { CourseModuleSlotNodeData } from "../ModuleSlotNode"
import { CourseModuleSlotNode } from "../ModuleSlotNode"
import { COURSE_MODULE_SLOT_NODE_TYPE } from "../moduleExpansion"
import { COURSE_ROOT_NODE_TYPE, CourseRootNode } from "../RootNode"
import { MindMapFullscreenButton } from "../MindMapFullscreenButton"
import { MindMapContinueButton } from "../MindMapContinueButton"
import { MindMapBackButton } from "../MindMapBackButton"
import { MindMapLegend } from "../MindMapLegend"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"

/**
 * Inner canvas: syncs graph from Redux course + highlights active module; follows app light/dark theme.
 */
export const Canvas = () => {
    const t = useTranslations()
    const locale = useLocale()
    const { resolvedTheme } = useTheme()
    const course = useAppSelector((state) => state.course.entity)
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    const activeModuleId = useAppSelector((state) => state.module.entity?.id)

    const themeMode: MindMapThemeMode = resolvedTheme === "dark" ? "dark" : "light"

    // Authenticated viewer's outline overlays progress onto the graph. Skips for guests /
    // the public standalone route (the hook returns no data when unauthenticated), so the
    // map degrades to a structure-only view.
    const { data: outline } = useQueryMyCourseOutlineSwr(courseId ?? null)
    const progress = useMemo(() => computeMindMapProgress(outline), [outline])

    /** Content-first resume target ΓÇö the map is a content surface, never the capstone. */
    const resumeHref = useMemo(
        () => (outline
            ? resolveContentHref(outline.nextContentTask, outline.modules, locale, displayId)
            : null),
        [outline, locale, displayId],
    )
    /** Outline known + nothing left to do ΓåÆ show the "all done" note instead of Continue. */
    const allContentDone = Boolean(outline && !outline.nextContentTask)

    const graph = useMemo(
        () => build({ course, activeModuleId, themeMode, progress }),
        [course, activeModuleId, themeMode, progress],
    )

    const [nodes, setNodes, onNodesChange] = useNodesState(graph.nodes)
    const [edges, setEdges, onEdgesChange] = useEdgesState(graph.edges)

    /** Holds slot nodes computed in `setNodes` so `setEdges` can keep matching edges in the same tick. */
    const preservedSlotsRef = useRef<Array<Node>>([])
    /** Canvas container ΓÇö target for the floating fullscreen button. */
    const containerRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        setNodes((prev) => {
            const keptSlots = prev.filter((node) => {
                if (node.type !== COURSE_MODULE_SLOT_NODE_TYPE) {
                    return false
                }
                const slotData = node.data as CourseModuleSlotNodeData
                return graph.nodes.some((base) => base.id === slotData.parentModuleId)
            })
            preservedSlotsRef.current = keptSlots
            return [...graph.nodes, ...keptSlots]
        })
        setEdges((prev) => {
            const mergedNodeIds = new Set([
                ...graph.nodes.map((node) => node.id),
                ...preservedSlotsRef.current.map((node) => node.id),
            ])
            const preservedExtras = prev.filter(
                (edge) =>
                    !graph.edges.some((base) => base.id === edge.id) &&
                    mergedNodeIds.has(edge.source) &&
                    mergedNodeIds.has(edge.target),
            )
            return [...graph.edges, ...preservedExtras]
        })
    }, [graph, setNodes, setEdges])

    const nodeTypes = useMemo(
        () => ({
            [COURSE_ROOT_NODE_TYPE]: CourseRootNode,
            [COURSE_MODULE_NODE_TYPE]: CourseModuleNode,
            [COURSE_MODULE_SLOT_NODE_TYPE]: CourseModuleSlotNode,
        }),
        [],
    )

    const { setCenter, fitView } = useReactFlow()

    /** Smoothly frames the clicked node: root ΓåÆ full overview, anything else ΓåÆ zoom to its center. */
    const onNodeClick = useCallback<NodeMouseHandler>(
        (_event, node) => {
            // clicking the course root pulls the camera back to the whole graph
            if (node.type === COURSE_ROOT_NODE_TYPE) {
                void fitView({
                    padding: 0.2,
                    duration: 600,
                })
                return
            }
            // otherwise animate the viewport to the node's measured center with a gentle zoom-in
            const width = node.measured?.width ?? 300
            const height = node.measured?.height ?? 100
            void setCenter(
                node.position.x + width / 2,
                node.position.y + height / 2,
                {
                    zoom: 1.4,
                    duration: 600,
                },
            )
        },
        [
            setCenter,
            fitView,
        ],
    )

    useMindMapFitView(progress.currentModuleId)

    if (!course) {
        return null
    }

    return (
        <div ref={containerRef} className="relative h-full w-full overflow-hidden bg-background/50 dark:bg-background/70">
            <ReactFlow
                aria-label={t("content.mindMapAria")}
                className="text-foreground"
                colorMode={themeMode}
                edges={edges}
                fitView
                fitViewOptions={{ padding: 0.2 }}
                maxZoom={2}
                minZoom={0.2}
                nodeTypes={nodeTypes}
                nodes={nodes}
                nodesConnectable={false}
                nodesDraggable={false}
                onEdgesChange={onEdgesChange}
                onNodeClick={onNodeClick}
                onNodesChange={onNodesChange}
                panOnScroll
                proOptions={{ hideAttribution: true }}
                zoomOnDoubleClick={false}
            >
                <Background gap={16} variant={BackgroundVariant.Dots} />
                <Controls
                    className="bg-surface shadow-sm dark:border-zinc-600 dark:bg-zinc-900/90"
                    showFitView={false}
                    showInteractive={false}
                    showZoom={false}
                >
                    <ControlButton
                        aria-label={t("mindMap.fitView")}
                        onClick={() => void fitView({ duration: 400, padding: 0.2 })}
                        title={t("mindMap.fitView")}
                    >
                        <FrameCornersIcon />
                    </ControlButton>
                </Controls>
                <MindMapBackButton />
                <MindMapFullscreenButton targetRef={containerRef} />
                <MindMapContinueButton resumeHref={resumeHref} allContentDone={allContentDone} />
                {outline ? <MindMapLegend /> : null}
            </ReactFlow>
        </div>
    )
}

"use client"

import React, { useCallback } from "react"
import { Button, Typography } from "@heroui/react"
import { Panel } from "@xyflow/react"
import { useRouter } from "next/navigation"
import { useTranslations } from "next-intl"
import { ArrowRightIcon } from "@phosphor-icons/react"

/** Props for {@link MindMapContinueButton}. */
export interface MindMapContinueButtonProps {
    /** Resume href for the viewer's next content task, or null when none resolvable. */
    resumeHref: string | null
    /** Whether the viewer has finished all content (outline known, nothing left). */
    allContentDone: boolean
}

/**
 * Floating primary "Continue" action for the mind-map: the single primary action on
 * the page. Jumps straight to the viewer's next unread lesson / uncompleted challenge
 * (content-first ΓÇö never the capstone, which resumes on its own surface). When all
 * content is done it shows a quiet "all done" note instead; for guests (no resume, not
 * done) it renders nothing.
 *
 * Must render as a child of {@link import("@xyflow/react").ReactFlow}.
 *
 * @param props - {@link MindMapContinueButtonProps}
 */
export const MindMapContinueButton = ({ resumeHref, allContentDone }: MindMapContinueButtonProps) => {
    const t = useTranslations()
    const router = useRouter()

    const onResume = useCallback(() => {
        if (resumeHref) {
            router.push(resumeHref)
        }
    }, [router, resumeHref])

    if (resumeHref) {
        return (
            <Panel className="!m-4" position="top-center">
                <Button
                    variant="primary"
                    aria-label={t("mindMap.continueAria")}
                    onPress={onResume}
                    className="rounded-full shadow-lg"
                >
                    {t("mindMap.continue")}
                    <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                </Button>
            </Panel>
        )
    }

    if (allContentDone) {
        return (
            <Panel className="!m-4 rounded-full bg-surface px-4 py-2 shadow-lg" position="top-center">
                <Typography type="body-sm" weight="semibold" className="text-success-soft-foreground">
                    {t("mindMap.allDone")}
                </Typography>
            </Panel>
        )
    }

    return null
}

"use client"

import React, { useCallback } from "react"
import { Handle, type Edge, type Node, type NodeProps, Position, useReactFlow, useStore } from "@xyflow/react"
import { cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CheckCircleIcon, LockIcon } from "@phosphor-icons/react"

import {
    CONTENT_OUTWARD_GAP,
    COURSE_MODULE_SLOT_NODE_TYPE,
    MODULE_CARD_BODY_HEIGHT,
    MODULE_CARD_WIDTH,
    MODULE_CHILD_SOURCE_HANDLE,
    MODULE_CONTENT_PREFIX,
    SLOT_NODE_HEIGHT,
    SLOT_NODE_WIDTH,
    SLOT_VERTICAL_STEP,
    moduleContentNodeId,
} from "../moduleExpansion"
import type { MindMapModuleStatus } from "../progress"

/** React Flow node type id for course modules (card + invisible handles). */
export const COURSE_MODULE_NODE_TYPE = "courseModule" as const

/** One lesson summary carried on a module node for on-click expansion. */
export type CourseModuleContentItem = {
    /** Lesson (content) id. */
    id: string
    /** Lesson label (order + title). */
    title: string
    /** Whether the viewer has read this lesson (drives the expanded card check). */
    isRead: boolean
}

/** React Flow node data for a `courseModule` node. */
export type CourseModuleNodeData = {
    /** Module title line (order + title). */
    label: string
    /** True when this module sits in the left column (target handle on the right). */
    isLeft: boolean
    /** Whether this module is the active selection in Redux. */
    isActive: boolean
    /** Whether this module owns the viewer's next content task ("you are here"). */
    isCurrent: boolean
    /** Coarse completion state of this module (tints the card). */
    status: MindMapModuleStatus
    /** Lessons the viewer has read in this module. */
    lessonsRead: number
    /** Total lessons in this module. */
    lessonsTotal: number
    /** Whether the whole module sits behind the premium paywall. */
    isLocked: boolean
    /** Whether a progress overlay is known (false ΓåÆ structure-only / guest). */
    hasProgress: boolean
    /** This module's id (parent for the expanded lesson cards). */
    moduleId: string
    /** Course mount slug ΓÇö threaded onto lesson cards for URL building. */
    courseDisplayId: string
    /** Real lessons of this module, expanded as child cards on click. */
    contents: Array<CourseModuleContentItem>
}

/** Card tint per completion status (token-based, dark-mode safe). */
const STATUS_TINT: Record<MindMapModuleStatus, string> = {
    done: "bg-success-soft border-success/40",
    inProgress: "bg-warning-soft border-warning/40",
    notStarted: "bg-surface border-separator",
}

/** React Flow node type for a `courseModule` node. */
export type CourseModuleFlowNode = Node<CourseModuleNodeData, typeof COURSE_MODULE_NODE_TYPE>

/**
 * Module node: click to reveal this module's real lessons as cards in the outer column.
 * Accordion ΓÇö opening one module collapses any other module's expanded lessons.
 * @param props ΓÇö React Flow `NodeProps` for `courseModule` nodes.
 */
export const CourseModuleNode = (props: NodeProps<CourseModuleFlowNode>) => {
    const { id, data, selected } = props
    const t = useTranslations()
    const { getNode, setNodes, setEdges } = useReactFlow()

    /** This module's lesson-card id prefix ΓÇö used to detect/strip its expanded nodes. */
    const contentPrefix = `${id}${MODULE_CONTENT_PREFIX}`

    // true when this module currently has its lessons expanded
    const expanded = useStore(
        useCallback(
            (state) => state.nodes.some((node) => node.id.startsWith(contentPrefix)),
            [contentPrefix],
        ),
    )

    const toggleContents = useCallback(() => {
        const self = getNode(id)
        if (!self) {
            return
        }

        // already open ΓåÆ collapse just this module's lessons
        if (getNode(moduleContentNodeId(id, data.contents[0]?.id ?? ""))) {
            setNodes((nodes) => nodes.filter((node) => !node.id.startsWith(contentPrefix)))
            setEdges((edges) => edges.filter((edge) => !edge.target.startsWith(contentPrefix)))
            return
        }

        if (data.contents.length === 0) {
            return
        }

        // lessons sit in the empty outer column (left module ΓåÆ further left, right ΓåÆ further right)
        const outerX = data.isLeft
            ? self.position.x - CONTENT_OUTWARD_GAP - SLOT_NODE_WIDTH
            : self.position.x + MODULE_CARD_WIDTH + CONTENT_OUTWARD_GAP
        // stack the lessons vertically centered on the module's center
        const moduleCenterY = self.position.y + MODULE_CARD_BODY_HEIGHT / 2
        const count = data.contents.length

        const contentNodes: Array<Node> = data.contents.map((content, index) => {
            const centerY = moduleCenterY + (index - (count - 1) / 2) * SLOT_VERTICAL_STEP
            return {
                id: moduleContentNodeId(id, content.id),
                type: COURSE_MODULE_SLOT_NODE_TYPE,
                position: { x: outerX, y: centerY - SLOT_NODE_HEIGHT / 2 },
                data: {
                    parentModuleId: id,
                    courseDisplayId: data.courseDisplayId,
                    moduleId: data.moduleId,
                    contentId: content.id,
                    label: content.title,
                    isLeft: data.isLeft,
                    isRead: content.isRead,
                },
                draggable: false,
                selectable: false,
            }
        })

        const contentEdges: Array<Edge> = data.contents.map((content) => ({
            id: `e-${moduleContentNodeId(id, content.id)}`,
            source: id,
            sourceHandle: MODULE_CHILD_SOURCE_HANDLE,
            target: moduleContentNodeId(id, content.id),
            type: "default",
            animated: false,
            style: {
                stroke: "var(--accent)",
                strokeWidth: 1.5,
                opacity: 0.85,
            },
        }))

        // accordion: drop every module's lesson nodes/edges, then add this module's
        setNodes((nodes) => [
            ...nodes.filter((node) => node.type !== COURSE_MODULE_SLOT_NODE_TYPE),
            ...contentNodes,
        ])
        setEdges((edges) => [
            ...edges.filter((edge) => !edge.target.includes(MODULE_CONTENT_PREFIX)),
            ...contentEdges,
        ])
    }, [getNode, id, data, contentPrefix, setEdges, setNodes])

    const onToggleKeyDown = useCallback(
        (event: React.KeyboardEvent<HTMLButtonElement>) => {
            if (event.key === "Enter" || event.key === " ") {
                event.preventDefault()
                toggleContents()
            }
        },
        [toggleContents],
    )

    return (
        <div
            className={cn(
                "relative flex min-h-[100px] min-w-[300px] w-[300px] flex-col items-stretch rounded-2xl px-4 py-3 text-center",
                "border shadow-sm transition-all duration-200 dark:shadow-lg dark:shadow-black/30",
                STATUS_TINT[data.status],
                // one accent ring scale (no per-state opacity zoo): hover = light ring,
                // selected/current = full ring, active = border only
                "hover:border-accent hover:shadow-md hover:ring-2 hover:ring-accent/30",
                data.isActive && "border-accent",
                // "you are here" ΓÇö strongest: accent border + full ring, wins over status border
                data.isCurrent && "border-accent ring-2 ring-accent",
                selected && "ring-2 ring-accent",
            )}
        >
            <Handle
                isConnectable={false}
                className="!h-px !w-px !min-h-0 !min-w-0 !border-0 !bg-transparent !opacity-0"
                position={data.isLeft ? Position.Right : Position.Left}
                type="target"
            />
            <Handle
                id={MODULE_CHILD_SOURCE_HANDLE}
                isConnectable={false}
                className="!h-px !w-px !min-h-0 !min-w-0 !border-0 !bg-transparent !opacity-0"
                position={data.isLeft ? Position.Left : Position.Right}
                type="source"
            />
            <button
                type="button"
                aria-expanded={expanded}
                aria-label={t("content.mindMapModuleToggleAria")}
                className={cn(
                    "nodrag nopan flex min-h-0 flex-1 w-full cursor-pointer flex-col items-center justify-center gap-2 rounded-2xl px-1 py-2 text-center outline-none",
                    "focus-visible:ring-2 focus-visible:ring-accent/40",
                )}
                onClick={() => {
                    // toggle lessons; the click also bubbles to ReactFlow `onNodeClick` to zoom-to-center
                    toggleContents()
                }}
                onKeyDown={onToggleKeyDown}
            >
                <div className="max-w-full text-pretty text-sm font-semibold leading-snug text-foreground">
                    {data.label}
                </div>
                {/* meta row: lock ┬╖ done ┬╖ lessons read count ┬╖ "you are here" ΓÇö light, one line */}
                <div className="flex flex-wrap items-center justify-center gap-2 text-xs leading-none text-muted">
                    {data.isLocked ? (
                        <LockIcon aria-label={t("mindMap.legend.locked")} focusable="false" className="size-4" />
                    ) : null}
                    {data.status === "done" ? (
                        <CheckCircleIcon aria-label={t("mindMap.legend.done")} focusable="false" className="size-4 text-success-soft-foreground" />
                    ) : null}
                    {data.hasProgress && data.lessonsTotal > 0 ? (
                        <span>
                            {t("mindMap.moduleLessons", { read: data.lessonsRead, total: data.lessonsTotal })}
                        </span>
                    ) : null}
                    {data.isCurrent ? (
                        <span className="font-medium text-accent-soft-foreground">{t("mindMap.legend.current")}</span>
                    ) : null}
                </div>
            </button>
        </div>
    )
}

/** Folder-matching handle for the module node ΓÇö an alias of {@link CourseModuleNode}. */
export const ModuleNode = CourseModuleNode

"use client"

import React, {
    useEffect,
    useMemo,
    useRef,
} from "react"
import {
    Background,
    BackgroundVariant,
    Controls,
    Handle,
    MiniMap,
    Position,
    ReactFlow,
    ReactFlowProvider,
    useReactFlow,
    useStore,
    type NodeProps,
    type NodeTypes,
} from "@xyflow/react"
import {
    Typography,
    cn,
} from "@heroui/react"
import { useAppSelector } from "@/redux/hooks"
import type {
    CourseMindMapData,
    CourseMindMapNodeData,
} from "@/modules/api/graphql/queries/types"
import type { MindMapRailTier as MindMapTier } from "@/components/blocks/learn/MindMapRail"
import {
    POP_RANK,
    TIER_MIN,
    tierAllows,
} from "@/modules/utils/mind-map"
import { MindMapNodeDrawer } from "@/components/overlays/drawers/MindMapNodeDrawer"

/** Border-ring tone per popularity tier (green / yellow / red) ΓÇö the ring signals how common a keyword is. */
const RING_BY_POP: Record<string, string> = {
    high: "border-success",
    medium: "border-warning",
    low: "border-danger",
}
/** MiniMap swatch colour per tier (SVG fill wants a concrete colour, not a utility class). */
const MINIMAP_BY_POP: Record<string, string> = {
    high: "#2f8f57",
    medium: "#c99a1e",
    low: "#c0392b",
}

/**
 * One authored KEYWORD ΓÇö a card whose RING colour encodes its popularity tier (green = very common,
 * yellow = common, red = specialized). The face carries ONLY the keyword; the explainer + related
 * surfaces (via RAG) live in the drawer that opens on click.
 */
const ConceptNode = ({ data, selected }: NodeProps) => {
    const node = data as unknown as CourseMindMapNodeData
    const ring = (node.popularity && RING_BY_POP[node.popularity]) || "border-default"
    return (
        <div
            className={cn(
                "max-w-[220px] rounded-2xl border-2 bg-surface px-3.5 py-2 shadow-surface transition-shadow hover:shadow-md",
                selected ? "border-accent" : ring,
            )}
        >
            <Handle type="target" position={Position.Left} className="!size-2 !border-0 !bg-transparent !opacity-0" />
            <Typography type="body-sm" weight="medium" className="line-clamp-2">
                {node.label}
            </Typography>
            <Handle type="source" position={Position.Right} className="!size-2 !border-0 !bg-transparent !opacity-0" />
        </div>
    )
}

/** The course root ΓÇö the trunk every branch hangs off. */
const RootNode = ({ data }: NodeProps) => {
    const node = data as unknown as CourseMindMapNodeData
    return (
        <div className="max-w-[220px] rounded-2xl bg-accent px-4 py-3 text-center shadow-surface">
            <Typography type="body-sm" weight="bold" className="text-accent-foreground line-clamp-2">
                {node.label}
            </Typography>
            <Handle type="source" position={Position.Right} className="!size-2 !border-0 !bg-transparent !opacity-0" />
        </div>
    )
}

/** Stable map ΓÇö React Flow re-mounts every node when this identity changes. */
const nodeTypes: NodeTypes = {
    concept: ConceptNode,
    course: RootNode,
}

/** Half a node's box ΓÇö `setCenter` wants the node CENTRE, positions are the top-left corner. */
const NODE_HALF_W = 110
const NODE_HALF_H = 20

/** Left margin (px) the course root is pinned to on the initial frame. */
const INITIAL_LEFT = 72
/** Readable-but-dense zoom the map opens at (small enough to show many, big enough to read). */
const INITIAL_ZOOM = 0.8

/**
 * Frames the map ONCE per mount: the course root pinned near the LEFT edge, vertically centred, at
 * a readable zoom ΓÇö so it opens the same way on every mount / F5 / re-mount (teacher 2026-07-18: "render
 * close to the course ┬╖ course name flush left ┬╖ small enough to render many, big enough to read"). Not `fitView` (which
 * centres the whole tree's bbox ΓåÆ an empty middle). Must live INSIDE the flow.
 */
const InitialFrame = ({
    nodes,
}: {
    nodes: CourseMindMapData["nodes"]
}) => {
    const { setViewport } = useReactFlow()
    const paneHeight = useStore((state) => state.height)
    const framed = useRef(false)
    useEffect(() => {
        if (framed.current || !paneHeight) {
            return
        }
        const root = nodes.find((candidate) => candidate.type === "course")
        if (!root) {
            return
        }
        framed.current = true
        void setViewport(
            {
                // root.x is 0 (column 0) ΓåÆ screen x = INITIAL_LEFT; y translated so root sits centred.
                x: INITIAL_LEFT,
                y: paneHeight / 2 - root.position.y * INITIAL_ZOOM,
                zoom: INITIAL_ZOOM,
            },
            { duration: 0 },
        )
    }, [paneHeight, nodes, setViewport])
    return null
}

/** Recentres the viewport on the selected node whenever it changes (must live INSIDE the flow). */
const FocusOnSelect = ({
    selectedId,
    nodes,
}: {
    selectedId: string | null
    nodes: CourseMindMapData["nodes"]
}) => {
    const { setCenter } = useReactFlow()
    useEffect(() => {
        if (!selectedId) {
            return
        }
        const node = nodes.find((candidate) => candidate.id === selectedId)
        if (node) {
            void setCenter(node.position.x + NODE_HALF_W, node.position.y + NODE_HALF_H, {
                zoom: 0.9,
                duration: 600,
            })
        }
    }, [selectedId, nodes, setCenter])
    return null
}

/** Props for {@link ConceptMap}. */
export interface ConceptMapProps {
    /** The full keyword graph (server-laid-out). */
    data: CourseMindMapData
    /** Live search text ΓÇö hides non-matching nodes (keeping matches + their ancestor path). */
    query: string
    /** Popularity floor ΓÇö dims lower tiers while browsing (no search). */
    tier: MindMapTier
    /** The node whose drawer is open + which the view is centred on (`null` = none). */
    selectedId: string | null
    /** Select a node (open its drawer + recentre) ΓÇö `null` closes. */
    onSelectId: (id: string | null) => void
}

/**
 * The keyword-map CANVAS (controlled) ΓÇö React Flow over the server's tidy-tree positions. Ring
 * colour = popularity; clicking a node (or a rail result) selects it ΓåÆ the view recentres
 * (`FocusOnSelect`) and its drawer (explainer + RAG surfaces) opens. Search HIDES non-matching
 * nodes but keeps each match's ancestor path so it never floats context-free; the tier filter dims
 * lower tiers while browsing. Filter + selection state is owned by the parent workspace.
 *
 * @param props - {@link ConceptMapProps}
 */
export const ConceptMap = ({
    data,
    query,
    tier,
    selectedId,
    onSelectId}: ConceptMapProps) => {
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)

    // when searching, the VISIBLE set = every match + its ancestor path + the root (so a matched
    // node never floats without its branch). `null` = no search ΓåÆ nothing hidden.
    const visible = useMemo(
        () => {
            const value = query.trim().toLowerCase()
            if (!value) {
                return null
            }
            const parentOf = new Map(data.edges.map((edge) => [edge.target, edge.source]))
            const set = new Set<string>()
            for (const node of data.nodes) {
                const nodeData = node.data as unknown as CourseMindMapNodeData
                if (node.type === "course") {
                    set.add(node.id)
                    continue
                }
                const matches = String(nodeData.label).toLowerCase().includes(value)
                    && tierAllows(nodeData.popularity, tier)
                if (matches) {
                    let cursor: string | undefined = node.id
                    while (cursor) {
                        set.add(cursor)
                        cursor = parentOf.get(cursor)
                    }
                }
            }
            return set
        },
        [query, tier, data],
    )

    const nodes = useMemo(
        () => data.nodes.map((node) => {
            const pop = (node.data as unknown as CourseMindMapNodeData).popularity
            // browsing (no search): dim tiers below the floor; searching: hide non-visible nodes.
            const dimmed = !visible && node.type !== "course" && pop
                ? POP_RANK[pop] < TIER_MIN[tier]
                : false
            return {
                id: node.id,
                type: node.type ?? "concept",
                position: node.position,
                data: node.data as unknown as Record<string, unknown>,
                selected: node.id === selectedId,
                hidden: visible ? !visible.has(node.id) : false,
                className: dimmed ? "opacity-15 transition-opacity" : "transition-opacity",
            }
        }),
        [data, tier, visible, selectedId],
    )
    const edges = useMemo(
        () => data.edges.map((edge) => ({
            id: edge.id,
            source: edge.source,
            target: edge.target,
            // bezier curves ("rounded line") read smoother than orthogonal steps.
            type: "default",
        })),
        [data],
    )

    const selectedData = selectedId
        ? (data.nodes.find((node) => node.id === selectedId)?.data as unknown as CourseMindMapNodeData | undefined)
        : undefined

    return (
        <div className={"relative h-full w-full"}>
            <ReactFlowProvider>
                <ReactFlow
                    nodes={nodes}
                    edges={edges}
                    nodeTypes={nodeTypes}
                    minZoom={0.1}
                    nodesDraggable={false}
                    nodesConnectable={false}
                    proOptions={{
                        hideAttribution: true,
                    }}
                    onNodeClick={(_event, node) => {
                        // root re-frames (deselect); every keyword selects ΓåÆ recentre + drawer.
                        onSelectId(node.type === "course" ? null : node.id)
                    }}
                    onPaneClick={() => onSelectId(null)}
                >
                    <Background variant={BackgroundVariant.Dots} gap={22} size={1} />
                    <Controls showInteractive={false} />
                    <MiniMap
                        pannable
                        zoomable
                        nodeColor={(node) => (node.type === "course"
                            ? "#c0407a"
                            : MINIMAP_BY_POP[String((node.data as unknown as CourseMindMapNodeData).popularity)] ?? "#c0c0c8")}
                    />
                    <InitialFrame nodes={data.nodes} />
                    <FocusOnSelect selectedId={selectedId} nodes={data.nodes} />
                </ReactFlow>
            </ReactFlowProvider>

            <MindMapNodeDrawer
                keyword={selectedData?.label ?? null}
                desc={selectedData?.desc ?? null}
                courseId={courseId ?? null}
                courseDisplayId={displayId ?? null}
                isOpen={Boolean(selectedId)}
                onClose={() => onSelectId(null)}
            />
        </div>
    )
}

import { InputTextarea } from "@/components/atoms/forms"
import React, { useState } from "react"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Button } from "@/components/atoms/buttons/Button"

import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK ΓÇö `ContentCommentComposer`: the textarea + submit control for new
 * comments, replies, and edits ΓÇö ONE component, three call shapes, ported
 * verbatim from real `src`'s `CommentComposer`. See the component's own file
 * header for why `variant="primary"` (real `Discussion` is frameless ΓÇö no
 * card ever wraps this field) and why the avatar-led row is top-level only.
 *
 * LEAVES by STRUCTURE (┬º14d.2). Collapsed-pill vs expanded-field is a real
 * node swap => separate leaves. Avatar present/absent is also a node swap
 * (top-level vs reply/edit) => its own leaf.
 */

/** Minimal identity for the avatar-led top-level composer. */
export interface ContentCommentComposerViewer {
    username: string
    avatarUrl?: string
}

/** Props for {@link ContentCommentComposer}. */
export interface ContentCommentComposerProps {
    /** Called with the trimmed body when the reader submits a non-empty comment. */
    onSubmit: (body: string) => void
    /** Placeholder text for the field. */
    placeholder?: string
    /** Submit button label. */
    submitLabel?: string
    /** Optional cancel handler ΓÇö renders a cancel button when provided (reply/edit). */
    onCancel?: () => void
    /** Initial field value (editing an existing comment). */
    initialValue?: string
    /** `true` -> submit is disabled and shows its busy affordance. */
    isPending?: boolean
    /**
 * Set -> the composer is avatar-led (top-level only; reply/edit omit this).
 * `null` -> signed-out top-level composer, no avatar.
 */
    currentUser?: ContentCommentComposerViewer | null
    /**
 * `true` -> starts collapsed as a slim avatar + placeholder pill, expands to
 * the full field on click (the top-level composer pattern). Reply/edit
 * composers omit this and render expanded.
 */
    collapsible?: boolean
    /** Accessible name for the field. */
    ariaLabel: string
    /** Where this sits inside its parent (placement only, e.g. `flex-1` beside a `ThreadConnector`). */
    classNames?: Array<AllowedClassName>
}

/**
 * The comment/reply/edit composer. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentComposerProps}
 */
const ContentCommentComposer = ({
    onSubmit: onSubmitAction,
    placeholder = "Ask a question or share your thoughtsΓÇª",
    submitLabel = "Post",
    onCancel: onCancelAction,
    initialValue,
    isPending = false,
    currentUser,
    collapsible = false,
    ariaLabel,
    classNames,
}: ContentCommentComposerProps) => {
    const [body, setBody] = useState(initialValue ?? "")
    // collapsible composers start closed; reply/edit always render expanded
    const [expanded, setExpanded] = useState(!collapsible)
    const trimmed = body.trim()

    const onSubmit = () => {
        if (!trimmed) {
            return
        }
        onSubmitAction(trimmed)
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        setBody("")
        if (collapsible) {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    // collapsed pill: avatar + placeholder, the whole row opens the composer
    if (collapsible && !expanded) {
        return (
            <StackH identity={{ tier: "block", component: "ContentCommentComposer" }}
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"

                items={[
                    ...(currentUser ? [() => (
                        <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
                    )] : []),
                    () => (
                        <div className="min-w-0 flex-1">
                            <InputButtonLike
                                placeholder={placeholder}
                                ariaLabel={ariaLabel}
                                onPress={() => setExpanded(true)}
                            />
                        </div>
                    ),
                ]}
            />
        )
    }

    const buttonRow = (
        <>
            <Button
                label={submitLabel}
                size="sm"
                onPress={onSubmit}
                isDisabled={!trimmed}
                isPending={isPending}

            />
            {onCancelAction || collapsible ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={onCancel}
                    isDisabled={isPending}

                />
            ) : null}
        </>
    )

    const fieldColumn = (
        <>
            <InputTextarea
                value={body}
                onValueChange={setBody}
                placeholder={placeholder}
                ariaLabel={ariaLabel}
                rows={3}
                variant="primary"

            />
            <StackH gap={3} items={[() => buttonRow]} />
        </>
    )

    const composerRow = (
        <>
            {currentUser ? (
                <Avatar src={currentUser.avatarUrl} name={currentUser.username} seed={currentUser.username} size="sm" />
            ) : null}
            <StackV gap={3} classNames={["min-w-0", "flex-1"]} items={[() => fieldColumn]} />
        </>
    )

    return (
        <StackH identity={{ tier: "block", component: "ContentCommentComposer" }} gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start" classNames={classNames} items={[() => composerRow]}  />
    )
}

export { ContentCommentComposer }

