                <SkeletonText size="xs" className="w-full" />
                <SkeletonText size="xs" className="w-3/4" />
            </div>
        ),
        [],
    )
    return (
        <AccordionSkeleton
            className={className}
            items={items}
            renderExpandedBody={renderExpandedBody}
        />
    )
}

/** CTA label ΓÇö a design CONSTANT, not opened to the caller (┬º14d.1). */
