    timeLeft?: string
    /** `true` ΓåÆ the `timeLeft` chip switches to `warning` tone. Only the TONE changes, not the element type. */
    urgent?: boolean
    /** Press handler. */
    onPress?: () => void
    /**
     * Navigation target ΓÇö ONLY `.Item` can use it (its CTA is `LinkSeeMore`, a real link).
     *
     * ΓÜá∩╕Å `.Hero` does NOT accept it: its CTA is `Button`, and the Button atom
     * **has no `href`** (it's a button, not a link). The old version dodged this by
     * hand-rolling a `<Link>` styled to look like a button ΓÇö exactly the drift being
     * cleaned up here, so it's dropped. `.Hero` navigates via `onPress` (the caller
     * does its own router-push); opening `href` for the button is work for the ATOM
     * tier, not a patch here.
     */
    href?: string
    /**
     * `true` ΓåÆ mirror shimmer INSTEAD of waiting for data. Applies to BOTH members
     * (`.Hero`/`.Item`) since both share `ContinueCardDataProps`.
     *
     * The flag FLOWS DOWN to the atom wherever an atom already has `isSkeleton`
     * (`Typography` for the title, `Button` for `.Hero`'s CTA, `SurfaceCard` for the card face).
     *
     * ΓÜá∩╕Å THREE spots in this tree have NO atom to take the flag, and the
     * scaffold/atom holding them sit OUTSIDE the 4 files touched this round (do not touch):
     *   ΓÇó the meta/subtitle row goes through scaffold `ListMeta` ΓÇö no `isSkeleton` yet;
     *   ΓÇó `ProgressMeter` (scaffold) ΓÇö no `isSkeleton` yet;
     *   ΓÇó `.Item`'s CTA goes through atom `LinkSeeMore` ΓÇö no `isSkeleton` yet.
     * Those three spots are TEXT/SHAPE rendered directly by CardBody/`.Item` (calling
     * the scaffold/atom straight, no layer in between), so they build their own
     * shimmer bar RIGHT HERE per the ┬º12c rule, instead of branching off to build a
     * parallel skeleton tree for the whole `ContinueCard`.
     */
    isSkeleton?: boolean
    /** The part name of THIS card itself (┬º11a). */
}

/** Props for {@link ContinueCardHero}. */
export type ContinueCardHeroProps = ContinueCardDataProps

/** Props for {@link ContinueCardItem}. */
export type ContinueCardItemProps = ContinueCardDataProps

import { GithubLogoIcon } from "@phosphor-icons/react"
import { Callout } from "@/components/composites/feedback/Callout"
import { Alert } from "@/components/atoms/feedback/Alert"

/**
 * `CourseTeamGate` ΓÇö a nudge to join the course's GitHub team. The backend
 * scopes the team by `is_enrolled = true`, so the block self-hides for trial
 * viewers and for anyone already in the team. Two leaves ΓÇö shown vs. hidden (a
 * node vs. an empty tree); the two hiding reasons produce the same empty tree,
 * so they are states of the hidden leaf.
 */

/** Props for {@link CourseTeamGate}. */
export interface CourseTeamGateProps {
    /**
     * Whether the learner has PAID for the course. Only paid learners have a team to
     * join (see header). Not known yet (query hasn't returned) ΓåÆ pass `false` so it
     * doesn't flicker.
     */
    isEnrolled: boolean
    /** Whether they're already in the GitHub team. `true` ΓåÆ the block self-hides. */
    isInTeam: boolean
    /** Fires when the join-team button is pressed. */
    onJoin?: () => void
    /**
     * `true` ΓåÆ render the shimmer mirror INSTEAD of waiting on `isEnrolled`/`isInTeam`
     * (not knowing yet means we can't decide whether to SELF-HIDE ΓÇö the mirror must
     * show to hold the slot in the loading tree).
     *
     * ΓÜá∩╕Å `Callout` (the frame this block still uses on the live branch) does
     * NOT have `isSkeleton` yet and sits OUTSIDE the 4 files touched this pass, so the
     * flag can't be forwarded through it. But `Callout` is just a thin wrapper
     * over the `Alert` atom ΓÇö and THAT atom already has `isSkeleton` (┬º12c). The
     * skeleton branch below calls `Alert` DIRECTLY (same `status`/`icon` that
     * `Callout` will use on the live branch) instead of hand-rolling a parallel
     * warning box.
     */
    isSkeleton?: boolean
}

/**
 * A non-blocking warning: the learner has paid but hasn't joined the course's
 * GitHub team yet (some labs need repo access). Self-hides when it doesn't apply.
 *
 * @param props - {@link CourseTeamGateProps}
 */
const CourseTeamGateBase = ({
    isEnrolled,
    isInTeam,
    onJoin,
    isSkeleton = false,
}: CourseTeamGateProps) => {
    // Loading: `isEnrolled`/`isInTeam` haven't come back yet, so we can't decide
    // whether to self-hide ΓÇö show the `Alert` atom's mirror (see the
    // `isSkeleton` doc above for why it calls the atom directly instead of
    // `Callout`).
    if (isSkeleton) {
        return (
            <Alert
                isSkeleton
                status="warning"
                icon={GithubLogoIcon}
            />
        )
    }

    // SELF-HIDE ΓÇö the block owns its own show condition; the screen doesn't need to ask.
    if (!isEnrolled || isInTeam) {
        return null
    }

    return (
        <Callout
            status="warning"
            icon={GithubLogoIcon}
            title="You haven't joined the course's GitHub team yet"
            description="Some labs need repo access ΓÇö tap to join."
            actionLabel="Join team"
            onAction={onJoin}
        />
    )
}

/** `CourseTeamGate.*` ΓÇö a single-component namespace ΓçÆ only has `.Base`. */
export { CourseTeamGateBase as CourseTeamGate }

