import React from "react"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { type LeaderboardPodiumEntry } from "../types"

/** Visual order leftΓåÆright on the dais: 2nd, 1st (centre), 3rd. */
const PODIUM_VISUAL_ORDER: Record<1 | 2 | 3, number> = { 2: 1, 1: 2, 3: 3 }
/** Riser height by rank ΓÇö 1st tallest, so the dais itself carries the ranking, not just a label. */
const PODIUM_RISER_HEIGHT: Record<1 | 2 | 3, string> = { 1: "h-20", 2: "h-14", 3: "h-10" }

/** Props for the internal {@link Podium} piece. */
interface PodiumProps {
    /** Top-3 finishers, in any order. */
    entries: Array<LeaderboardPodiumEntry>
    /** Accessible tag for "this is you", forwarded from the block. */
    meLabel: string
    isSkeleton: boolean
}

/** One podium dais entry: avatar, username, score line, ranked riser. */
const podiumEntryCard = (entry: LeaderboardPodiumEntry, meLabel: string, isSkeleton: boolean) => {
    const riser = (
        <div className={`flex w-full items-center justify-center rounded-t-xl bg-accent-soft ${PODIUM_RISER_HEIGHT[entry.rank]}`}>
            {/* real `src` (`Podium/index.tsx:103-112`): the rank number is a BARE div,
                declaring no size at all (inherits base/16px), just `font-bold` ΓÇö not `lg`. */}
            <Typography
                size="base"
                weight="bold"
                tabularNums
                isSkeleton={isSkeleton}
                text={isSkeleton ? undefined : String(entry.rank)}
                color="accent-soft"

            />
        </div>
    )
    return (
        <div key={entry.rank} className="w-24">
            <StackV
                gap={2}
                principle="title-subtitle"
                explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                align="center"
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <div>
                            <Avatar
                                name={entry.username}
                                src={entry.avatar ?? undefined}
                                seed={entry.username}
                                size={entry.rank === 1 ? "lg" : "md"}
                                isSkeleton={isSkeleton}

                            />
                        </div>
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            color={entry.isMe ? "accent" : undefined}
                            truncate
                            align="center"
                            isSkeleton={isSkeleton}
                            text={isSkeleton ? undefined : entry.username}
                            classNames={["w-full"]}

                        />
                    ),
                    () => (
                        <Typography
                            size="xs"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={isSkeleton ? undefined : entry.pointsLabel}

                        />
                    ),
                    () => riser,
                    ...(entry.isMe ? [() => <span className="sr-only">{meLabel}</span>] : []),
                ]}
            />
        </div>
    )
}

/** One podium dais entry: avatar, username, score line, ranked riser. */
export const Podium = ({ entries, meLabel, isSkeleton }: PodiumProps) => (
    <StackH
        gap={3}
        principle="sibling-stack"
        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
        justify="center"
        align="end"
        isSkeleton={isSkeleton}
        items={[...entries]
            .sort((a, b) => PODIUM_VISUAL_ORDER[a.rank] - PODIUM_VISUAL_ORDER[b.rank])
            .map((entry) => () => podiumEntryCard(entry, meLabel, isSkeleton))}
    />
)

"use client"

import React from "react"
import { Label, ListBox, Typography, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import {
    BookOpenIcon,
    FlagIcon,
    PuzzlePieceIcon,
    TrophyIcon,
} from "@phosphor-icons/react"
import type { Icon } from "@phosphor-icons/react"
import {
    categoryMyXp,
    parseCategoryParam,
    type LeaderboardCategoryKey,
} from "@/modules/utils/leaderboard"
import { useLeaderboardSwr } from "@/hooks/swr/api/graphql/queries/useLeaderboardSwr"

/** One row in the category rail. */
interface RailItem {
    key: LeaderboardCategoryKey
    icon: Icon
    label: string
    /** Viewer's XP in this category. */
    xp: number
    /** Optional muted caption ("9 lessons ┬╖ ├ù3" / "Coming soon"). */
    caption?: string
    disabled?: boolean
}

/** Props for {@link LeaderboardCategoryRail}. */
export interface LeaderboardCategoryRailProps {
    /**
     * `rail` ΓÇö the sidebar-style vertical list (desktop left rail, in the learn
     * shell's `leftRail` slot). `chips` ΓÇö a horizontal scroll of pills above the
     * board (mobile, where the rail is hidden).
     */
    variant: "rail" | "chips"
}

/**
 * The XP-category selector ΓÇö doubles as the viewer's XP composition (each row shows
 * *your* XP in that category) and the board's sort control. Self-contained: reads
 * the shared leaderboard fetch + drives the selection through the `?category=` URL
 * param, so it works from the left rail (a different layout slot than the board)
 * with no shared React state. `total` is the canonical ranking; `coding` is
 * disabled until the backend scores it per-course.
 *
 * @param props - {@link LeaderboardCategoryRailProps}
 */
export const LeaderboardCategoryRail = ({ variant }: LeaderboardCategoryRailProps) => {
    const t = useTranslations()
    const router = useRouter()
    const pathname = usePathname()
    const searchParams = useSearchParams()
    const { data } = useLeaderboardSwr()
    const myRank = data?.myRank ?? null

    const selected = parseCategoryParam(searchParams.get("category"))
    const onSelect = (key: LeaderboardCategoryKey) => {
        // merge into the existing query (preserve other params, joined with `&`)
        const params = new URLSearchParams(searchParams.toString())
        params.set("category", key)
        router.replace(`${pathname}?${params.toString()}`, { scroll: false })
    }

    const items: Array<RailItem> = [
        {
            key: "total",
            icon: TrophyIcon,
            label: t("leaderboard.categories.total"),
            xp: categoryMyXp(myRank, "total"),
        },
        {
            key: "challenge",
            icon: PuzzlePieceIcon,
            label: t("leaderboard.categories.challenge"),
            xp: categoryMyXp(myRank, "challenge"),
            caption: t("leaderboard.categories.captionChallenge", { count: myRank?.completedChallenges ?? 0 }),
        },
        {
            key: "reading",
            icon: BookOpenIcon,
            label: t("leaderboard.categories.reading"),
            xp: categoryMyXp(myRank, "reading"),
            caption: t("leaderboard.categories.captionReading", { count: myRank?.lessonsRead ?? 0 }),
        },
        {
            key: "milestone",
            icon: FlagIcon,
            label: t("leaderboard.categories.milestone"),
            xp: categoryMyXp(myRank, "milestone"),
            caption: t("leaderboard.categories.captionMilestone", { count: myRank?.milestoneProgress ?? 0 }),
        },
    ]

    // mobile: a horizontal scroll of category chips above the board
    if (variant === "chips") {
        return (
            <div className="-mx-1 flex gap-2 overflow-x-auto px-1 pb-1">
                {items.map((item) => {
                    const isSelected = item.key === selected
                    return (
                        <button
                            key={item.key}
                            type="button"
                            disabled={item.disabled}
                            onClick={() => onSelect(item.key)}
                            className={cn(
                                "flex shrink-0 cursor-pointer items-center gap-2 rounded-full border px-3 py-2 text-sm transition-colors",
                                isSelected ? "border-accent bg-accent-soft text-accent-soft-foreground" : "border-default text-muted hover:bg-default",
                                item.disabled && "cursor-not-allowed opacity-55",
                            )}
                        >
                            {/* icon inherits the button's text colour (muted / accent-soft
                                when selected) ΓÇö same colour as the label, per the teacher's note. */}
                            <item.icon aria-hidden focusable="false" className="size-4 shrink-0" />
                            <span>{item.label}</span>
                            {!item.disabled ? (
                                <span className="font-medium">{t("leaderboard.xp", { xp: item.xp })}</span>
                            ) : null}
                        </button>
                    )
                })}
            </div>
        )
    }

    // desktop: vertical sidebar-style list (lives in the shell's left rail slot)
    return (
        <div className="flex flex-col gap-3 overflow-y-auto p-6">
            <Label>{t("leaderboard.categories.label")}</Label>
            <ListBox
                aria-label={t("leaderboard.categories.label")}
                selectionMode="single"
                disallowEmptySelection
                selectedKeys={[selected]}
                onSelectionChange={(keys) => {
                    // controlled single-select ΓåÆ drive the URL from the chosen key
                    const key = [...keys][0] as LeaderboardCategoryKey | undefined
                    if (key) {
                        onSelect(key)
                    }
                }}
                className="gap-1 p-0"
            >
                {items.map((item) => (
                    <ListBox.Item
                        key={item.key}
                        id={item.key}
                        textValue={item.label}
                        isDisabled={item.disabled}
