import React from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    LockIcon,
} from "@phosphor-icons/react"
import {
    useRouter,
} from "next/navigation"
import {
    useSidebarNavItems,
} from "@/hooks/useSidebarNavItems"
import type {
    LearnNavBadge,
    LearnNavGroup,
} from "@/components/layouts/LearnShellLayout/types"
import { Chip } from "@/components/atoms/chips/Chip"
import { ResumeRail } from "../ResumeRail"
import { CollapsibleSidebar } from "@/components/blocks/navigation/CollapsibleSidebar"
import { SidebarNavGroup } from "@/components/blocks/navigation/SidebarNavGroup"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { SidebarNavAccordionGroup } from "@/components/blocks/navigation/SidebarNavAccordionGroup"

/** localStorage key persisting the learn course-nav collapsed flag. */
const SIDEBAR_STORAGE_KEY = "starci.learn.sidebar.collapsed"

/**
 * Order the labelled nav clusters render in: the mandatory spine (path), then the
 * aids (practice), then the meta surfaces (track). The first group has no divider;
 * every later group gets a full-width {@link SidebarNavGroup} divider on top.
 */
const GROUP_ORDER: ReadonlyArray<LearnNavGroup> = ["path", "practice", "track"]

/**
 * Render a row's trailing status badge: a warning-tinted due-card count, or the
 * viewer's rank as accent text. Kept small so it doesn't crowd the label.
 *
 * @param badge - The {@link LearnNavBadge} to render.
 * @returns The badge node.
 */
const renderBadge = (badge: LearnNavBadge): React.ReactNode => {
    if (badge.tone === "rank") {
        return (
            <Typography type="body-xs" className="text-accent-soft-foreground">
                {`#${badge.value}`}
            </Typography>
        )
    }
    return (
        <Chip tone="warning" text={String(badge.value)} />
    )
}

/** Props for {@link LearnSidebar}. */
export type LearnSidebarProps = Record<string, never>
/**
 * Course-learn left navigation rail (desktop).
 *
 * Container: pulls the shared nav entries from {@link useSidebarNavItems} and
 * composes the {@link CollapsibleSidebar} block ΓÇö which owns the collapse-in-place
 * animation, the toggle, the divider, and persisting the collapsed flag. Rows are
 * split into separator-divided clusters by their `group` (study / practice);
 * each row is a {@link SidebarNavItem} that self-dispatches its tab + navigation
 * through the shared select handler. Hidden below `lg` (mobile uses the drawer in
 * {@link import("../LearnMobileBar").LearnMobileBar}). `"use client"` for the hooks.
 *
 * @param props - {@link LearnSidebarProps}
 */
export const LearnSidebar = () => {
    const t = useTranslations()
    const router = useRouter()
    // shared entries + active tab (also used by the mobile drawer)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // role-group captions (sentence case ΓÇö no uppercase)
    const groupLabels: Record<LearnNavGroup, string> = {
        path: t("nav.groupPath"),
        practice: t("nav.groupPractice"),
        track: t("nav.groupTrack"),
    }
    return (
        <CollapsibleSidebar
            title={t("nav.courseMenu")}
            collapseLabel={t("nav.collapseLeftRail")}
            expandLabel={t("nav.expandLeftRail")}
            storageKey={SIDEBAR_STORAGE_KEY}
            topSlot={<ResumeRail />}
        >
            {GROUP_ORDER.map((group, index) => {
                // rows belonging to this cluster, in their declared order
                const groupItems = items.filter((item) => item.group === group)
                if (groupItems.length === 0) {
                    return null
                }
                return (
                    // first cluster has no divider; later clusters get the full-width separator
                    <SidebarNavGroup key={group} divider={index > 0} label={groupLabels[group]}>
                        {groupItems.map((item) => (
                            item.children ? (
                                <SidebarNavAccordionGroup
                                    key={item.value}
                                    icon={item.icon}
                                    label={item.label}
                                    items={item.children.map((child) => ({
                                        value: child.value,
                                        label: child.label,
                                        isActive: child.isActive,
                                        onPress: () => router.push(child.url),
                                    }))}
                                />
                            ) : (
                                <SidebarNavItem
                                    key={item.value}
                                    icon={<item.icon className="size-5 shrink-0" />}
                                    label={item.label}
                                    isActive={selectedTab === item.tab}
                                    endContent={item.locked ? (
                                        <LockIcon
                                            aria-label={t("enrollGate.locked")}
                                            focusable="false"
                                            className="size-4 text-muted"
                                        />
                                    ) : item.badge ? renderBadge(item.badge) : undefined}
                                    onPress={() => onSelect(item)}
                                />
                            )
                        ))}
                    </SidebarNavGroup>
                )
            })}
        </CollapsibleSidebar>
    )
}

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
} from "react"
import {
    useRouter,
} from "next/navigation"
import {
    useLocale,
} from "next-intl"
import {
    useTranslations,
} from "next-intl"
import {
    pathConfig,
} from "@/resources/path"
import {
    MilestoneIndexStrip,
} from "./MilestoneIndexStrip"
import { useQueryMilestonesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestonesSwr"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { useAppSelector, useAppDispatch } from "@/redux/hooks"
import { setSelectedTaskId } from "@/redux/slices/milestone"
import { OutlineRail } from "@/components/blocks/navigation/OutlineRail"
import type { OutlineRailGroup } from "@/components/blocks/navigation/OutlineRail"
import type { MilestoneEntity } from "@/modules/types/entities/milestone"
import { buildMilestoneTaskProgressLookup, isPersonalProjectTaskActionUnlocked } from "@/components/utils/task-lookup"

/**
 * Props for {@link MilestoneOutline}.
 */
type MilestoneOutlineProps = {
    /** Collapsed mode: render a slim numbered index instead of the full list. */
    collapsed?: boolean
}

/**
 * Filter milestones + their tasks by a lower-cased query (milestone title match keeps
 * all its tasks; otherwise only matching tasks survive). Empty query ΓåÆ unchanged.
 */
const filterMilestones = (
    milestones: Array<MilestoneEntity>,
    query: string,
): Array<MilestoneEntity> => {
    if (!query) {
        return milestones
    }
    const result: Array<MilestoneEntity> = []
    for (const milestone of milestones) {
        const matches = (milestone.title ?? "").toLowerCase().includes(query)
        const tasks = matches
            ? (milestone.tasks ?? [])
            : (milestone.tasks ?? []).filter((task) => task.title.toLowerCase().includes(query))
        if (matches || tasks.length > 0) {
            result.push({ ...milestone, tasks })
        }
    }
    return result
}

/**
 * Milestone navigation rail for the personal-project capstone ΓÇö rendered through
 * the SAME shared {@link OutlineRail} block as the course content-map, so the two
 * rails look identical (progress header + "Go to current lesson" continue, search, and
 * milestone ΓåÆ task rows). This is a thin data wrapper: owns the milestones/progress
 * SWR singletons, the Redux task selection + unlock logic, and the controlled
 * search/expand state; it maps milestonesΓåÆgroups and tasksΓåÆrows for the block.
 *
 * `collapsed` keeps the slim numbered {@link MilestoneIndexStrip} for the rail's
 * collapse handle. `"use client"` for hooks.
 * @param props - optional collapsed flag
 */
export const MilestoneOutline = ({ collapsed = false }: MilestoneOutlineProps) => {
    const t = useTranslations()
    const milestonesSwr = useQueryMilestonesSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const dispatch = useAppDispatch()
    const router = useRouter()
    const locale = useLocale()
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)

    /** Milestones sorted by their display order. */
    const milestones = useMemo(
        () => [...milestoneEntities].sort((prev, next) => prev.sortIndex - next.sortIndex),
        [milestoneEntities],
    )

    /** Build a map of taskId -> progress item for quick lookup. */
    const progressMap = useMemo(
        () => buildMilestoneTaskProgressLookup(
            progressSwr.data?.milestoneTaskProgress?.data?.completionTasks,
        ),
        [progressSwr.data],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    /** Whether a task is unlocked (all previous tasks completed or it's the current task). */
    const isTaskUnlocked = useCallback(
        (taskId: string) => isPersonalProjectTaskActionUnlocked(taskId, progressMap, currentTaskId),
        [progressMap, currentTaskId],
    )

    /** Select a task: store the id in redux and route to its learn page. */
    const onSelectTask = useCallback(
        (taskId: string) => {
            dispatch(setSelectedTaskId(taskId))
            router.push(
                pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(taskId).build(),
            )
        },
        [dispatch, router, locale, courseDisplayId],
    )

    /** Milestone that owns the currently selected task. */
    const activeMilestoneId = useMemo(() => {
        if (!selectedTaskId) {
            return undefined
        }
        const owner = milestones.find((milestone) =>
            (milestone.tasks ?? []).some((task) => task.id === selectedTaskId))
        return owner ? String(owner.id) : undefined
    }, [milestones, selectedTaskId])

    // ---- collapsed rail (slim numbered index) -------------------------------
    /** Collapsed-rail press: jump to the first task of the chosen milestone. */
    const onSelectMilestone = useCallback(
        (milestoneId: string) => {
            const milestone = milestones.find((entity) => String(entity.id) === milestoneId)
            const firstTask = (milestone?.tasks ?? [])
                .slice()
                .sort((prev, next) => prev.sortIndex - next.sortIndex)[0]
            if (firstTask) {
                onSelectTask(firstTask.id)
            }
        },
        [milestones, onSelectTask],
    )

    // ---- search + controlled expand (mirrors ContentMap) --------------------
    const [search, setSearch] = useState("")
    const query = search.trim().toLowerCase()
    const filteredMilestones = useMemo(
        () => filterMilestones(milestones, query),
        [milestones, query],
    )

    const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set())
    useEffect(() => {
        if (!activeMilestoneId) {
            return
        }
        setExpandedKeys((prev) => prev.has(activeMilestoneId) ? prev : new Set(prev).add(activeMilestoneId))
    }, [activeMilestoneId])
    useEffect(() => {
        if (query) {
            setExpandedKeys(new Set(filteredMilestones.map((milestone) => String(milestone.id))))
        }
    }, [query, filteredMilestones])

    // ---- header progress (tasks done / total across all milestones) ---------
    const taskTotals = useMemo(() => {
        let done = 0
        let total = 0
        for (const milestone of milestones) {
            for (const task of milestone.tasks ?? []) {
                total += 1
                if (progressMap.get(task.id)?.completed) {
                    done += 1
                }
            }
        }
        return { done, total }
    }, [milestones, progressMap])

    // ---- milestones ΓåÆ rail groups -------------------------------------------
    const groups = useMemo<Array<OutlineRailGroup>>(
        () => filteredMilestones.map((milestone) => {
            const tasks = (milestone.tasks ?? [])
                .slice()
                .sort((prev, next) => prev.sortIndex - next.sortIndex)
            const doneCount = tasks.filter((task) => progressMap.get(task.id)?.completed).length
            return {
                id: String(milestone.id),
                title: `${milestone.sortIndex}. ${milestone.title || "Milestone"}`,
                progress: { done: doneCount, total: tasks.length },
                collapsedCountLabel: t("courseContents.moduleLessons", {
                    read: doneCount,
                    total: tasks.length,
                }),
                items: tasks.map((task) => ({
                    id: task.id,
                    title: `${task.sortIndex}. ${task.title}`,
                    isActive: selectedTaskId === task.id,
                    isRead: progressMap.get(task.id)?.completed ?? false,
                    isLocked: !isTaskUnlocked(task.id),
                    isPremium: false,
                    onPress: () => onSelectTask(task.id),
                })),
            }
        }),
        [filteredMilestones, progressMap, selectedTaskId, isTaskUnlocked, onSelectTask, t],
    )

    // loading gate: prefer cached redux milestones (SWR hydrates into entities)
    const hasData = milestones.length > 0
    const isLoading = !hasData && !milestonesSwr.error && (milestonesSwr.isLoading || !milestonesSwr.data)
    const isEmpty = !hasData && !milestonesSwr.isLoading && !!milestonesSwr.data && !milestonesSwr.error

    // collapsed rail: only the slim numbered index (clicking a number jumps to that milestone)
    if (collapsed) {
        return (
            <div className="@app-lg:min-h-0 @app-lg:flex-1 @app-lg:overflow-y-auto">
                <MilestoneIndexStrip
                    milestones={milestones}
                    activeMilestoneId={activeMilestoneId}
                    onSelectMilestone={onSelectMilestone}
                />
            </div>
        )
    }

    return (
        <OutlineRail
            className="@app-lg:min-h-0 @app-lg:flex-1"
            header={taskTotals.total > 0 ? {
                label: t("courseContents.progress"),
                progress: { done: taskTotals.done, total: taskTotals.total },
                countLabel: t("courseContents.contentCount", {
                    read: taskTotals.done,
                    total: taskTotals.total,
                }),
                continue: currentTaskId && currentTaskId !== selectedTaskId ? {
                    label: t("task.previewLockedGoToCurrentTaskButton"),
                    onPress: () => onSelectTask(currentTaskId),
                } : undefined,
            } : undefined}
            search={{
                value: search,
                onChange: setSearch,
                placeholder: t("finalProject.page.searchTaskPlaceholder"),
                ariaLabel: t("finalProject.page.searchTaskPlaceholder"),
            }}
            groups={groups}
            expandedKeys={expandedKeys}
            onExpandedChange={setExpandedKeys}
            isSkeleton={isLoading}
            async={{
                isEmpty,
                emptyTitle: t("courseContents.empty"),
                errorTitle: t("task.loadErrorTitle"),
                error: !hasData ? milestonesSwr.error : undefined,
                onRetry: () => { void milestonesSwr.mutate() },
                retryLabel: t("courseContents.retry"),
                noMatchLabel: t("courseContents.noMatch"),
            }}
        />
    )
}

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"

/**
 * `MockInterviewAnswerAction` ΓÇö the one control that submits the candidate's
 * current answer and advances the live interview. Exists as a one-node block so the
 * screen tier need not import a bare `Button` directly; it holds the
 * `isLastQuestion` decision and wording the button alone cannot own. `isLastQuestion`
 * / `isDisabled` / `isPending` flip the same button's label and press-ability.
 */

/** Props for {@link MockInterviewAnswerAction}. */
export interface MockInterviewAnswerActionProps {
    /** `true` ΓåÆ this is the run's final question; swaps the label to the finishing wording. */
    isLastQuestion: boolean
    /** Fired when the candidate submits the current answer. */
    onSubmit: () => void
    /** `true` ΓåÆ the caller has decided this press cannot fire right now (e.g. a blank answer, or the interviewer still mid-turn). */
    isDisabled?: boolean
    /** `true` ΓåÆ the submit request is in flight. */
    isPending?: boolean
}

/**
 * The live interview's one submit action. See the file header for why this
 * exists as its own block instead of a bare `Button` in the screen tree.
 *
 * @param props - {@link MockInterviewAnswerActionProps}
 */
const MockInterviewAnswerAction = ({
    isLastQuestion,
    onSubmit,
    isDisabled = false,
    isPending = false,
}: MockInterviewAnswerActionProps) => (
    <Button
        variant="primary"
        size="lg"
        label={isLastQuestion ? "Answer & finish" : "Answer & continue"}
        suffixIcon={ArrowRightIcon}
        iconSlide
        onPress={onSubmit}
        isDisabled={isDisabled}
        isPending={isPending}
        classNames={["self-center"]}

    />
)

