"use client"

import React, { useCallback, useEffect, useRef, useState } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useParams, useRouter } from "next/navigation"
import {
    Button,
    Chip,
    Label,
    ScrollShadow,
    Spinner,
    Typography,
} from "@heroui/react"
import {
    ArrowLeftIcon,
    ArrowRightIcon,
    CubeIcon,
    LinkSimpleIcon,
} from "@phosphor-icons/react"
import { ConnectSheet } from "@/components/blocks/layout/ConnectSheet"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { StatRibbon } from "@/components/composites/stats/StatRibbon"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { PlaygroundHeader } from "@/components/blocks/learn/PlaygroundHeader"
import { usePlaygroundSessionContext } from "@/components/providers/PlaygroundSessionProvider"
import { pathConfig } from "@/resources/path"

/** One reported resource, as the agent snapshots it. */
interface ReportedResource {
    kind: string
    name: string
    status: string
}

/**
 * Bucket a flat resource snapshot by `kind`, preserving first-seen order for
 * both the groups and the rows inside them.
 *
 * The agent reports one flat array (`Container`, `Image`, `Pod`, ΓÇª); rendering
 * it flat means 50+ undifferentiated rows where the learner has to read every
 * name to find the one the step is about. Kind is the axis they scan by.
 *
 * @param resources - Flat snapshot from `resources:report`.
 * @returns Groups in first-appearance order, each with its rows.
 */
const groupResourcesByKind = (
    resources: Array<ReportedResource>,
): Array<{ kind: string, items: Array<ReportedResource> }> => {
    const groups: Array<{ kind: string, items: Array<ReportedResource> }> = []
    const byKind = new Map<string, { kind: string, items: Array<ReportedResource> }>()
    for (const resource of resources) {
        let group = byKind.get(resource.kind)
        if (!group) {
            group = { kind: resource.kind, items: [] }
            byKind.set(resource.kind, group)
            groups.push(group)
        }
        group.items.push(resource)
    }
    return groups
}

/**
 * Chip color per resource status ΓÇö also free-form raw text (`"Running"`,
 * `"Present"`, `"2/2 ready"`, `"ClusterIP"`, ...). A simple substring
 * heuristic ("running"/"ready"/"present"/"active" reads success) covers every
 * status the current Docker/K8s steps report; anything else stays neutral.
 */
const resourceStatusColor = (status: string): "success" | "default" => {
    const normalized = status.toLowerCase()
    if (/running|present|active|clusterip|nodeport/.test(normalized)) {
        return "success"
    }
    const readyMatch = normalized.match(/^(\d+)\/(\d+) ready$/)
    if (readyMatch && readyMatch[1] === readyMatch[2] && readyMatch[1] !== "0") {
        return "success"
    }
    return "default"
}

/**
 * Playground session ΓÇö the full-bleed 2-pane hands-on work surface for one
 * course-scoped Docker/K8s exercise. LEFT: the current step's guide (the
 * command to run in the learner's OWN terminal) + a single "connect your
 * machine" flow (connected ΓåÆ waiting/dropped) with a live latency readout +
 * a link back to the Setup route to reconnect/switch machine. RIGHT: the
 * workspace ΓÇö an {@link EmptyState} placeholder until the machine pairs, then
 * a live Resources snapshot fed by the learner's local CLI agent relayed over
 * the `/playground_byom` socket. Modeled on `PracticeProblem`'s full-bleed
 * 2-pane archetype.
 *
 * There is deliberately NO in-browser terminal: the learner runs commands in
 * their own, and "Re-check" asks the paired agent to re-snapshot
 * resources on demand (`verify:now`) so the step can confirm what actually
 * happened on their machine.
 *
 * The socket + session are owned by {@link usePlaygroundSessionContext} (mounted
 * at the route layout) ΓÇö this component is the LAB surface only; pairing lives
 * on the Setup (`[slug]`) route.
 */
export const PlaygroundCliSession = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // Course from the URL, NOT the store ΓÇö playgrounds are shared by every course,
    // so a stale `state.course.displayId` navigates the learner out of theirs.
    const params = useParams()
    const courseDisplayId = String(params.courseId ?? "")

    const { playground, byomState, requestVerify, everConnected, slug } = usePlaygroundSessionContext()

    const [currentStepIndex, setCurrentStepIndex] = useState(0)
    // Whether the docked ConnectSheet is expanded. CONTROLLED so it auto-snaps per
    // connection state (expanded while the learner must wait, collapsed once
    // connected); the user can still drag/tap the sheet to override until the
    // next state change.
    const [sheetOpen, setSheetOpen] = useState(false)

    const steps = playground?.steps ?? []
    const currentStep = steps[currentStepIndex]
    // `rag`-kind playgrounds swap the CLI-agent Terminal/Resources for the
    // self-contained RAG importΓåÆaskΓåÆcite widget, and walk steps MANUALLY
    // (no agent to server-verify each step) ΓÇö see the kind-branch below.
    const isRag = playground?.kind === "rag"

    // Render any shell command through MarkdownContent's code fence (one canonical
    // style: mono + slim lang header + copy). `elevated` picks the surface
    // treatment by CONTAINER: raised card ON the canvas (left pane, bg-background),
    // recessed well ON a surface (the ConnectSheet body, bg-surface) ΓÇö an elevated
    // bg-surface card on the bg-surface sheet would be surface-in-surface (axis-1 ┬º16).
    const renderCommand = useCallback(
        (command: string, elevated: boolean) => (
            <MarkdownContent markdown={`\`\`\`bash\n${command}\n\`\`\``} codeElevated={elevated} />
        ),
        [],
    )

    const onPrevStep = useCallback(() => {
        setCurrentStepIndex((prev) => Math.max(0, prev - 1))
    }, [])
    const onNextStep = useCallback(() => {
        setCurrentStepIndex((prev) => Math.min(steps.length - 1, prev + 1))
    }, [steps.length])

    const onLeave = useCallback(() => {
        router.push(pathConfig().locale(locale).course(courseDisplayId).learn().playground().build())
    }, [router, locale, courseDisplayId])

    // auto-snap the ConnectSheet per connection state: EXPAND while the learner
    // must wait (not connected yet / just dropped), COLLAPSE once connected
    // (workspace is the focus). The user can drag/tap to override until the
    // next state change.
    useEffect(() => {
        if (isRag) {
            return
        }
        setSheetOpen(!byomState.connected)
    }, [isRag, byomState.connected])

    // "checkingΓÇª" while a verify request is in flight, and a "not done yet" hint
    // when it lands without advancing the step.
    const [verifying, setVerifying] = useState(false)
    const [verifyMissed, setVerifyMissed] = useState(false)

    // advance to the step the agent just verified (server-driven, not a local guess)
    useEffect(() => {
        if (byomState.verifiedStepIndex === null) {
            return
        }
        setCurrentStepIndex((prev) => Math.max(prev, byomState.verifiedStepIndex! + 1))
        // a verify landed ΓåÆ clear the pending / miss UI.
        setVerifying(false)
        setVerifyMissed(false)
    }, [byomState.verifiedStepIndex])

    // "Verify" = ask the agent to report resources NOW; the backend matches them to
    // the step and pushes `step:verified`. It does NOT re-run the command (the
    // learner runs that on their own machine), so clicking never triggers a
    // "container already in use" conflict.
    const onConfirmStep = useCallback(() => {
        setVerifyMissed(false)
        setVerifying(true)
        requestVerify()
    }, [requestVerify])

    // bound the "checkingΓÇª" window; if the step didn't advance, hint the learner to
    // run the command first.
    useEffect(() => {
        if (!verifying) {
            return
        }
        const handle = setTimeout(() => {
            setVerifying(false)
            setVerifyMissed(true)
        }, 2500)
        return () => clearTimeout(handle)
    }, [verifying])

    // keep the agent log pinned to its newest line as it streams.
    const agentLogRef = useRef<HTMLDivElement>(null)
    useEffect(() => {
        const el = agentLogRef.current
        if (el) {
            el.scrollTop = el.scrollHeight
        }
    }, [byomState.agentLog])

    // ΓöÇΓöÇ ConnectSheet content (peek row + expanded body) ΓöÇΓöÇ
    // connected ΓåÆ success + live latency + a link back to Setup to reconnect;
    // not connected ΓåÆ warning status (first-time "waiting" vs. later "dropped",
    // per `everConnected`). The body carries the device specs + agent log.
    const sheetPeek = byomState.connected ? (
        <div className="flex flex-wrap items-center gap-2">
            <StatusChip tone="success">
                {byomState.latencyMs !== null
                    ? t("playground.session.agentConnectedLatency", { ms: byomState.latencyMs })
                    : t("playground.session.agentConnected")}
            </StatusChip>
            <Button
                className="ml-auto"
                size="sm"
                variant="danger-soft"
                onPress={() => router.push(pathConfig().locale(locale).course(courseDisplayId).learn().playground(slug).build())}
            >
                {t("playground.session.reconnect")}
            </Button>
        </div>
    ) : (
        <StatusChip tone="warning">
            {everConnected
                ? t("playground.session.agentDisconnected")
                : t("playground.session.agentWaiting")}
        </StatusChip>
    )

    // ΓöÇΓöÇ connected body: device config tiles + agent log ΓöÇΓöÇ
    const gb = (bytes: number) => Math.round(bytes / 1e9)
    const platformLabel = (p: string) =>
        p === "win32" ? "Windows" : p === "darwin" ? "macOS" : p === "linux" ? "Linux" : p
    const device = byomState.deviceInfo
    // Device specs render as ONE StatRibbon (a single Card with vertical dividers ΓÇö
    // the canon "ribbon"), NOT N hand-rolled tiles which read as surface-in-surface
    // on the bg-surface sheet. Each pair carries the category plus the specific behind
    // it, which the ribbon draws as its own second line.

    const connectedBody = (
        <div className="flex flex-col gap-4">
            {device ? (
                <div className="flex flex-col gap-2">
                    <Label>{t("playground.session.deviceTitle")}</Label>
                    <StatRibbon
                        bordered
                        valueType="body"
                        items={[
                            {
                                key: "os",
                                value: platformLabel(device.platform),
                                label: t("playground.session.deviceOs"),
                                detail: `${device.arch} ┬╖ ${device.hostname}`,
                            },
                            {
                                key: "cpu",
                                value: t("playground.session.deviceCores", { count: device.cpuCores }),
                                label: t("playground.session.deviceCpu"),
                                detail: device.cpuModel,
                            },
                            {
                                key: "ram",
                                value: `${gb(device.totalMemBytes)} GB`,
                                label: t("playground.session.deviceRam"),
                                detail: t("playground.session.deviceRamFree", { gb: gb(device.freeMemBytes) }),
                            },
                            {
                                key: "gpu",
                                value: device.gpu ?? "ΓÇö",
                                label: t("playground.session.deviceGpu"),
                                detail: device.vramTotalMb
                                    ? `${Math.round(device.vramTotalMb / 1024)} GB VRAM${device.vramFreeMb != null ? ` ┬╖ ${device.vramFreeMb} MB ${t("playground.session.deviceVramFree")}` : ""}`
                                    : device.gpu ? undefined : t("playground.session.deviceGpuUnknown"),
                            },
                        ]}
                    />
                </div>
            ) : null}
            {byomState.agentLog.length > 0 ? (
                <div className="flex flex-col gap-2">
                    <Label>{t("playground.session.agentLogTitle")}</Label>
                    <div ref={agentLogRef} className="max-h-40 overflow-y-auto rounded-2xl border border-default bg-default p-3 font-mono text-xs leading-relaxed">
                        {byomState.agentLog.map((entry, index) => (
                            <div
                                key={index}
                                className={`break-words ${
                                    entry.level === "success"
                                        ? "text-success-soft-foreground"
                                        : entry.level === "warn"
                                            ? "text-warning-soft-foreground"
                                            : entry.level === "error"
                                                ? "text-danger-soft-foreground"
                                                : "text-muted"
                                }`}
                            >
                                {entry.line}
                            </div>
                        ))}
                    </div>
                </div>
            ) : null}
        </div>
    )

    // The sheet is a STATUS strip now (PA-3): machine specs + agent log while
    // connected, and a pointer back to the Setup surface when it drops ΓÇö the
    // install/pair instructions live there, not duplicated here.
    const sheetBody = byomState.connected ? (
        connectedBody
    ) : (
        <Typography type="body-sm" color="muted">
            {t("playground.session.reconnectFromPrepareHint")}
        </Typography>
    )

    return (
        <div className="flex h-[calc(100vh-4rem)] flex-col">
            <PlaygroundHeader step={{ current: currentStepIndex + 1, total: steps.length }} />

            {/* `relative` so the docked ConnectSheet (absolute bottom) anchors here. */}
            <div className="relative grid flex-1 grid-cols-1 overflow-hidden @app-lg:grid-cols-2">
                {/* ΓöÇΓöÇ LEFT: step guide + verify (connection lives in the ConnectSheet) ΓöÇΓöÇ
                bg-background (page canvas): the code blocks here render as
                RAISED cards (`codeElevated` ΓåÆ bg-surface + shadow) so they
                "float up" off the canvas, instead of a recessed well that
                would blend canvas-on-canvas (axis-1 ┬º16). pb-24 clears the
                collapsed sheet peek docked at the bottom. */}
                <div className="flex flex-col overflow-y-auto border-r border-default bg-background px-6 pt-5 pb-24">
                    {currentStep ? (
                        <div className="flex flex-col gap-4">
                            <Typography type="h6" weight="bold">
                                {currentStep.title}
                            </Typography>
                            <MarkdownContent markdown={currentStep.body} codeElevated />
                            {/* elevated card: the left pane is bg-background canvas ΓåÆ the
                            command "floats up" (axis-1 ┬º16). */}
                            {currentStep.commandHint ? renderCommand(currentStep.commandHint, true) : null}
                            {/* rag-kind steps carry an actionHint (what to do in the widget) instead of a shell command */}
                            {currentStep.actionHint ? (
                                <div className="rounded-medium border border-dashed border-default bg-default px-3 py-2 text-sm">
                                    <MarkdownContent markdown={currentStep.actionHint} />
                                </div>
                            ) : null}

                            <div className="border-t border-default pt-4">
                                {isRag ? (
                                    // rag path: no CLI agent ΓÇö the learner works in the RAG widget
                                    // on the right and walks the steps manually.
                                    <div className="flex items-center gap-2">
                                        <Button
                                            variant="tertiary"
                                            isDisabled={currentStepIndex === 0}
                                            onPress={onPrevStep}
                                        >
                                            <ArrowLeftIcon aria-hidden focusable="false" className="size-4" />
                                            {t("playground.session.prevStep")}
                                        </Button>
                                        <Button
                                            variant="primary"
                                            isDisabled={currentStepIndex >= steps.length - 1}
                                            onPress={onNextStep}
                                        >
                                            {t("playground.session.nextStep")}
                                            <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                        </Button>
                                    </div>
                                ) : byomState.connected ? (
                                    // machine paired ΓåÆ VERIFY this step (checks resources; never re-runs
                                    // the command, so no "container already in use" conflict).
                                    <div className="flex flex-col gap-2">
                                        <Button variant="primary" isPending={verifying} onPress={onConfirmStep}>
                                            {verifying ? <Spinner size="sm" aria-hidden /> : null}
                                            {t(verifying ? "playground.session.verifying" : "playground.session.confirmStep")}
                                        </Button>
                                        {verifyMissed ? (
                                            <Typography type="body-xs" color="muted">
                                                {t("playground.session.verifyMissed")}
                                            </Typography>
                                        ) : null}
                                    </div>
                                ) : (
                                    // not connected ΓåÆ point to the ConnectSheet docked below.
                                    <Typography type="body-sm" color="muted">
                                        {t("playground.session.connectFromSheetHint")}
                                    </Typography>
                                )}
                            </div>
                        </div>
                    ) : (
                        <AsyncContentEmpty
                            title={t("playground.session.completeTitle")}
                            description={t("playground.session.completeDescription")}
                            onRetry={onLeave}
                            retryLabel={t("playground.session.backToHub")}
                        />
                    )}
                </div>

                {/* ΓöÇΓöÇ RIGHT: kind-branched workspace ΓöÇΓöÇ
                ONE concept for the pre-connected state (waiting + dropped):
                a single EmptyState. The Terminal / Resources workspace only
                appears once the machine actually pairs. bg-surface = a full
                surface panel (the workspace reads as one solid surface, while
                the left guide pane sits on the page canvas). */}
                <div className="flex flex-col overflow-hidden bg-surface">
                    {!byomState.connected ? (
                        <div className="flex h-full items-center justify-center p-6">
                            <EmptyState
                                icon={CubeIcon}
                                title={t("playground.session.workspaceLockedTitle")}
                                description={t("playground.session.workspaceLockedHint")}
                            />
                        </div>
                    ) : (
                        <div className="flex h-full flex-col overflow-hidden">
                            {/* single-pane header ΓÇö no tab strip: the learner runs commands in
                            their OWN terminal, so this Resources snapshot IS the whole workspace. */}
                            <div className="flex items-center gap-2 border-b border-default px-4 py-3">
                                <CubeIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />
                                <Typography type="body-sm" weight="medium">
                                    {t("playground.session.tabs.resources", { count: byomState.resources.length })}
                                </Typography>
                            </div>

                            <div className="min-h-0 flex-1 overflow-hidden p-4 pb-20">
                                {byomState.resources.length === 0 ? (
                                    <div className="flex h-full items-center justify-center">
                                        <EmptyState
                                            icon={LinkSimpleIcon}
                                            title={t("playground.session.resourcesEmptyTitle")}
                                            description={t("playground.session.resourcesEmptyDescription")}
                                        />
                                    </div>
                                ) : (
                                    // Grouped by KIND, each group collapsible. A flat list of
                                    // every object on the machine (55+ here, mostly the
                                    // learner's own unrelated containers) is unreadable, and
                                    // the kind is the axis they actually scan by. The row also
                                    // drops the big IconTile: inside a group whose header
                                    // already names the kind, a per-row tile repeats it 20├ù.
                                    <ScrollShadow hideScrollBar className="flex h-full flex-col overflow-y-auto">
                                        {/* Accordion card grouped by kind. NO `label`: the header
                                                above is already the heading, so a label here is label-on-label
                                                (accordion.md ┬º3d). `bordered` = the pane is a nested surface.
                                                The count rides in the header via `titleEnd`; each row is a
                                                ListRow inside the panel body. */}
                                        <LabeledAccordionCard
                                            bordered
                                            allowsMultipleExpanded
                                            defaultExpandedKeys={new Set(groupResourcesByKind(byomState.resources).map((group) => group.kind))}
                                            items={groupResourcesByKind(byomState.resources).map((group) => ({
                                                id: group.kind,
                                                // the kind name already says "Container / Image / Network",
                                                // so no leading glyph ΓÇö it would just repeat the label
                                                title: group.kind,
                                                titleEnd: () => (
                                                    <Typography type="body-xs" color="muted">{group.items.length}</Typography>
                                                ),
                                                body: () => group.items.map((resource, index) => (
                                                    <ListRow
                                                        key={`${resource.kind}-${resource.name}`}
                                                        title={resource.name}
                                                        trailing={(
                                                            <Chip
                                                                size="sm"
                                                                variant="soft"
                                                                color={resourceStatusColor(resource.status)}
                                                            >
                                                                {resource.status}
                                                            </Chip>
                                                        )}
                                                        divider={index < group.items.length - 1}
                                                    />
                                                )),
                                            }))}
                                        />
                                    </ScrollShadow>
                                )}
                            </div>
                        </div>
                    )}
                </div>

                {/* ΓöÇΓöÇ ConnectSheet: docked, draggable connection console ΓöÇΓöÇ
                RAG labs need no agent ΓåÆ no sheet. Auto-snaps per connection
                state; the learner can drag/tap to override. */}
                {!isRag ? (
                    <ConnectSheet
                        open={sheetOpen}
                        onOpenChange={setSheetOpen}
                        toggleLabel={t("playground.session.sheetToggle")}
                        peek={sheetPeek}
                    >
                        {sheetBody}
                    </ConnectSheet>
                ) : null}
            </div>
        </div>
    )
}

import React from "react"
import { ArrowRightIcon, CheckCircleIcon } from "@phosphor-icons/react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * `PlaygroundEnterBanner` ΓÇö the playground page's single primary decision card.
 * Reuses `FlashcardDueHero`'s card shape (`SurfaceCard` Γèâ `StackV` Γèâ status line +
 * primary `Button`). The block builds its own readiness sentence from `allReady` +
 * `pendingCount`. One shape: ready vs pending are data states ΓÇö the swap only
 * changes the status text/color and the CTA's `isDisabled`.
 */

/** Props for {@link PlaygroundEnterBanner}. */
export interface PlaygroundEnterBannerProps {
    /** `true` ΓåÆ every prerequisite step is done and the room can be entered. */
    allReady: boolean
    /** How many prerequisite steps are still outstanding. Ignored when `allReady`. */
    pendingCount: number
    /** Fired when the learner presses the primary CTA. Only reachable when `allReady`. */
    onEnter: () => void
    /**
     * `true` ΓåÆ the status line and the button switch to their own shimmer. The
     * flag flows straight into the composed `Typography`/`Button` atoms rather
     * than a parallel skeleton tree (┬º12c).
     */
    isSkeleton?: boolean
}

/** The section label above the card ΓÇö also doubles as the CTA's own wording (the decision this whole card is). */
const SECTION_LABEL = "Continue"

/**
 * Builds the readiness sentence from raw data (┬º14d.1) ΓÇö never handed a
 * pre-formatted string by the caller.
 */
const buildReadinessText = (allReady: boolean, pendingCount: number): string =>
    allReady
        ? "All prep steps are done ΓÇö ready to enter the lab."
        : `${pendingCount} steps left before you can enter.`

/**
 * The playground page's single primary decision card. See the file header
 * for the full contract, especially the "gated, not swallowed" note.
 *
 * @param props - {@link PlaygroundEnterBannerProps}
 */
const PlaygroundEnterBanner = ({
    allReady,
    pendingCount,
    onEnter,
    isSkeleton = false,
}: PlaygroundEnterBannerProps) => {
    const readiness = buildReadinessText(allReady, pendingCount)
    return (
        <SurfaceCard identity={{ tier: "block", component: "PlaygroundEnterBanner" }}
            label={SECTION_LABEL}

            isSkeleton={isSkeleton}

            body={() => (
                <StackV
                    gap={4}
                    isSkeleton={isSkeleton}
                    items={[
                        () => (
                            <Typography
                                size="sm"
                                color={allReady ? "success" : "muted"}
                                weight={allReady ? "medium" : undefined}
                                prefixIcon={allReady ? CheckCircleIcon : undefined}
                                isSkeleton={isSkeleton}

                                text={readiness}
                            />
                        ),
                        () => (
                            <Button
                                variant="primary"
                                label={SECTION_LABEL}
                                suffixIcon={ArrowRightIcon}
                                iconSlide
                                onPress={onEnter}
                                isDisabled={!allReady}
                                isSkeleton={isSkeleton}

                                classNames={["w-fit"]}
                            />
                        ),
                    ]}
                />
            )}
        />
    )
}

export { PlaygroundEnterBanner }

import React from "react"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `PlaygroundHubHeader` ΓÇö the hub-identity cluster at the top of the
 * Docker/Kubernetes exercise grid: a title and an optional one-sentence purpose
 * line. Sibling of `ContentHeader`/`FoundationsHeader` but thinnest ΓÇö no breadcrumb,
 * meta row, or secondary card. One shape: `isSkeleton` only swaps which state the
 * `Typography` renders inside the same `PageHeader`.
 */

/** Props for {@link PlaygroundHubHeader}. */
export interface PlaygroundHubHeaderProps {
    /** Hub title, e.g. "Playground". */
    title: string
    /** One-sentence purpose line explaining what the hub is for. */
    description?: string
    /**
     * `true` ΓåÆ the composed `Typography` slots switch to their own shimmer.
     * The flag FLOWS DOWN into the real atoms rather than building a parallel
     * skeleton tree (┬º12c).
     */
    isSkeleton?: boolean
}

/**
 * The playground-hub identity cluster at the top of the exercise grid. See
 * the file header for the full contract and why this stays thinner than its
 * `ContentHeader`/`FoundationsHeader` siblings.
 *
 * @param props - {@link PlaygroundHubHeaderProps}
 */
const PlaygroundHubHeader = ({
    title,
    description,
    isSkeleton = false,
}: PlaygroundHubHeaderProps) => {
    return (
        <PageHeader
            isSkeleton={isSkeleton}
            title={title}
            description={description}
        />
    )
}

export { PlaygroundHubHeader }

import React from "react"
import { CircleDashedIcon, CubeIcon, PlugsIcon } from "@phosphor-icons/react"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { ListRow } from "@/components/composites/lists/List"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `PlaygroundResourcePanel` ΓÇö the right pane of the playground screen, the live
 * workspace: nothing until the paired machine reports in, then the resource
 * snapshot the socket sent, grouped by kind. Reuses `SurfaceCard.Accordion`,
 * `List.Row`, and `EmptyState` rather than inventing its own. Status uses `Chip`,
 * not `EnumChip`, because it is free-form CLI text ("Up 2 hours", "Exited (0)"): a
 * `toneForStatus` heuristic degrades to neutral on anything unrecognized. One shape,
 * three states (not-connected, connected-empty, connected-with-resources) ΓÇö a header
 * row over a body region whose fill changes.
 */

/** Whether the playground's paired machine is reachable right now. */
export type PlaygroundConnectionState = "notConnected" | "connected"

/** One resource line as the socket reports it ΓÇö flat, ungrouped, free-form status text. */
export interface PlaygroundResourceEntry {
    /** What kind of resource this is (`"Container"`, `"Image"`, `"Pod"`...) ΓÇö the block's own group key. */
    kind: string
    /** The resource's name/id as the agent reports it ΓÇö assumed unique within its `kind`. */
    name: string
    /** Free-form status text straight from the CLI (`"Up 2 hours"`, `"Exited (0)"`...). */
    status: string
}

/** Props for {@link PlaygroundResourcePanel}. */
export interface PlaygroundResourcePanelProps {
    /** Whether the paired machine is reachable right now. */
    connection: PlaygroundConnectionState
    /**
     * The flat resource snapshot as the socket reports it. Ignored while
     * `connection === "notConnected"`. Empty while connected means the machine
     * paired but hasn't reported a snapshot yet.
     */
    resources: Array<PlaygroundResourceEntry>
}

/** The panel's own fixed header wording ΓÇö see the file header for why this isn't a prop. */
const PANEL_LABEL = "Resources"

/** One resource kind bucket, in first-seen order. */
interface PlaygroundResourceGroup {
    kind: string
    resources: Array<PlaygroundResourceEntry>
}

/**
 * Buckets the flat snapshot by `kind`, preserving each kind's FIRST-SEEN order ΓÇö
 * see the file header for why there's no hardcoded kind priority table.
 */
const groupByKind = (resources: ReadonlyArray<PlaygroundResourceEntry>): Array<PlaygroundResourceGroup> => {
    const order: Array<string> = []
    const byKind = new Map<string, Array<PlaygroundResourceEntry>>()
    for (const resource of resources) {
        if (!byKind.has(resource.kind)) {
            byKind.set(resource.kind, [])
            order.push(resource.kind)
        }
        byKind.get(resource.kind)?.push(resource)
    }
    return order.map((kind) => ({ kind, resources: byKind.get(kind) ?? [] }))
}

/** First letter uppercased only ΓÇö the kind arrives as one word from the agent (`"container"`, `"pod"`...). */
const titleCaseKind = (kind: string): string => (kind.length === 0 ? kind : kind[0].toUpperCase() + kind.slice(1))

// Checked in this ORDER: a status can contain more than one signal word (e.g.
// "unhealthy" contains "healthy"), so the negative buckets are matched first ΓÇö
// see the file header for why this heuristic exists instead of a closed enum.
const DANGER_STATUS = /\b(exited|dead|error|failed?|crash(ed)?|unhealthy|stopped)\b/i
const WARNING_STATUS = /\b(restarting|creating|pending|paused|starting|stopping|degraded)\b/i
const SUCCESS_STATUS = /\b(running|ready|active|healthy|up)\b/i

/** Free-form CLI status text ΓåÆ chip tone. Unrecognized text degrades to `"default"`, never throws. */
const toneForStatus = (status: string): ChipTone => {
    if (DANGER_STATUS.test(status)) return "danger"
    if (WARNING_STATUS.test(status)) return "warning"
    if (SUCCESS_STATUS.test(status)) return "success"
    return "default"
}

/** Builds one kind group's accordion row: trigger = kind + count, panel = one `List.Row` per resource. */
const groupToAccordionItem = (group: PlaygroundResourceGroup): SurfaceCardAccordionItem => ({
    id: group.kind,
    title: titleCaseKind(group.kind),
    titleEnd: () => (
        <Chip
            tone="default"
            text={String(group.resources.length)}

        />
    ),
    body: () => (
        <StackV
            gap={1}
            principle="sibling-stack"
            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."

            items={group.resources.map((resource, index) => () => (
                <ListRow
                    title={resource.name}
                    meta={() => (
                        <Chip
                            tone={toneForStatus(resource.status)}
                            text={resource.status}

                        />
                    )}
                    divider={index < group.resources.length - 1}

                />
            ))}
        />
    ),
})

/**
 * The playground's live-workspace pane. See the file header for the full
 * contract (grouping, the status heuristic, and the one-leaf/three-state call).
 *
 * @param props - {@link PlaygroundResourcePanelProps}
 */
const PlaygroundResourcePanel = ({
    connection,
    resources,
}: PlaygroundResourcePanelProps) => {
    const isConnected = connection === "connected"
    const hasResources = isConnected && resources.length > 0

    const groups = hasResources ? groupByKind(resources) : []

    const body = !isConnected ? (
        <EmptyState
            icon={PlugsIcon}
            title="Not paired yet"
            description="Pair a machine to see the resources running in your workspace."

        />
    ) : !hasResources ? (
        <EmptyState
            icon={CircleDashedIcon}
            title="Waiting for data"
            description="Machine paired ΓÇö waiting for the first resource snapshot."

        />
    ) : (
        <SurfaceCardAccordion
            items={groups.map((group) => groupToAccordionItem(group))}
            allowsMultipleExpanded
            defaultExpandedKeys={new Set(groups.map((group) => group.kind))}


        />
    )

    const headerRow = (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            justify="between"
            align="center"

            items={[
                () => (
                    <Typography
                        size="sm"
                        weight="medium"
                        prefixIcon={CubeIcon}
                        text={PANEL_LABEL}

                    />
                ),
                // A count of zero (or no snapshot at all) is not news ΓÇö see `ContentModeNav`'s
                // "a count of zero is not news" convention ΓÇö so it only appears once there's
                // something real to count.
                ...(hasResources ? [() => (
                    <Typography
                        size="xs"
                        color="muted"
                        tabularNums
                        text={String(resources.length)}

                    />
                )] : []),
            ]}
        />
    )

    return (
        <StackV identity={{ tier: "block", component: "PlaygroundResourcePanel" }}
            gap={4}

            items={[
                () => headerRow,
                () => body,
            ]}
        />
    )
}

