"use client"

import React, { useCallback, useMemo, useState } from "react"
import { Chip, Link, Spinner, cn } from "@heroui/react"
import { PushPinIcon, SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import type { CourseQuestionNode } from "@/modules/api/graphql/queries/types/course-questions"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { Composer } from "@/components/blocks/feed/Composer"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { ReactionBar } from "@/components/blocks/community/Discussion/ReactionBar"
import { QaInboxRow } from "../QaInboxRow"
import { QaConversationHeader, type QaConversationHeaderPerson } from "../QaConversationHeader"
import { QaMessageBubble } from "../QaMessageBubble"
import { useQuestionAnswers } from "@/hooks/swr/api/graphql/queries/useQuestionAnswersSwr"
import { useMutateSetFollowSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetFollowSwr"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link QaQuestionThread}. */
export interface QaQuestionThreadProps {
    /** The question to render. */
    question: CourseQuestionNode
    /** Current viewer id (drives own-bubble alignment + owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Current viewer identity for the answer composer avatar; null when signed out. */
    currentUser: { username: string, avatar?: string } | null
    /** Called after an answer is posted/edited/deleted ΓÇö bumps the parent roll-up's aggregates. */
    onAnswered?: () => void
}

/**
 * One course-Q&A conversation. Collapsed, it is a social {@link QaInboxRow} (asker,
 * preview, scope tag, answered/unanswered status, reply count, status dot). Pressing
 * it expands the FULL conversation inline: a {@link QaConversationHeader} (asker +
 * who-joined-in avatar group), the question itself rendered as the first chat bubble
 * (with its lesson-funnel tag + status), then every answer as a {@link QaMessageBubble}
 * ΓÇö the viewer's own messages align right, peers + founder align left ΓÇö and a
 * bottom {@link Composer} to add an answer. This is the ONLY place to answer a
 * course-general question (it has no lesson page of its own).
 *
 * Owns the expand state + the answer thread's data/persistence (via
 * {@link useQuestionAnswers}, gated on `expanded` so nothing fetches until opened).
 *
 * @param props - {@link QaQuestionThreadProps}
 */
export const QaQuestionThread = ({ question, currentUserId, currentUser, onAnswered}: QaQuestionThreadProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // display id (slug) builds the lesson route the question's tag links to
    const displayId = useAppSelector((state) => state.course.displayId)

    // answer-thread toggle; the answers are gated on `expanded` inside the facade hook,
    // so opening the conversation the first time is what triggers the fetch
    const [expanded, setExpanded] = useState(false)
    // draft + in-flight guard for the bottom "add an answer" composer
    const [answerDraft, setAnswerDraft] = useState("")
    const [isPostingAnswer, setIsPostingAnswer] = useState(false)

    const {
        answers,
        isLoadingAnswers,
        answerRepliesByParent,
        onReply,
        onEdit,
        onDelete,
        onReactComment,
        onReactQuestion,
        onAcceptAnswer,
        onLoadReplies,
    } = useQuestionAnswers(question.id, expanded, onAnswered)

    const isMineQuestion = currentUserId !== null && currentUserId === question.author.id
    const questionName = isMineQuestion ? t("courseQa.you") : (question.author.displayName || question.author.username)

    // follow the asker ΓÇö local optimistic state seeded from the server flag; only the
    // viewer's own toggle mutates it, so no re-sync on list refetch is needed
    const { trigger: triggerSetFollow, isMutating: isFollowPending } = useMutateSetFollowSwr()
    const [isFollowingAsker, setIsFollowingAsker] = useState(question.author.isFollowedByMe)
    // never follow yourself; hide the control when signed out or on your own question
    const canFollowAsker = currentUserId !== null && currentUserId !== question.author.id
    const onToggleFollow = useCallback(async () => {
        const next = !isFollowingAsker
        const result = await triggerSetFollow({ userId: question.author.id, follow: next })
        // commit only on a confirmed success (mirrors the league board's follow flow)
        if (result?.data?.setFollow?.success) {
            setIsFollowingAsker(next)
        }
    }, [isFollowingAsker, triggerSetFollow, question.author.id])

    // distinct answerers ΓåÆ the "who joined in" avatar group in the header
    const participants = useMemo<Array<QaConversationHeaderPerson>>(() => {
        const seen = new Set<string>()
        const list: Array<QaConversationHeaderPerson> = []
        for (const answer of answers) {
            if (!seen.has(answer.author.id)) {
                seen.add(answer.author.id)
                list.push({
                    id: answer.author.id,
                    displayName: answer.author.username,
                    avatarUrl: answer.author.avatar ?? undefined,
                })
            }
        }
        return list
    }, [answers])

    /**
     * Route to the source lesson ΓÇö the funnel back into the course content. A no-op
     * for a course-general question (no `contentId`/`moduleId` to route to).
     */
    const goToLesson = useCallback(() => {
        if (!displayId || !question.contentId || !question.moduleId) {
            return
        }
        router.push(
            pathConfig()
                .locale(locale)
                .course(displayId)
                .learn()
                .module(question.moduleId)
                .content(question.contentId)
                .build(),
        )
    }, [displayId, locale, router, question.contentId, question.moduleId])

    /** Post a new top-level answer via the bottom composer, then clear the draft. */
    const submitAnswer = useCallback(async () => {
        const body = answerDraft.trim()
        if (!body) {
            return
        }
        setIsPostingAnswer(true)
        try {
            await onReply(question.id, body)
            setAnswerDraft("")
        } finally {
            setIsPostingAnswer(false)
        }
    }, [answerDraft, onReply, question.id])

    // collapsed ΓÇö a flush social inbox row inside the parent's SurfaceListCard
    if (!expanded) {
        return (
            <QaInboxRow
                question={question}
                onOpen={() => setExpanded(true)}
            />
        )
    }

    // expanded ΓÇö the full conversation, rendered inline in place of the row
    return (
        <div className={"flex flex-col gap-4 p-3"}>
            <QaConversationHeader
                asker={{
                    id: question.author.id,
                    displayName: question.author.displayName || question.author.username,
                    avatarUrl: question.author.avatar ?? undefined,
                }}
                isFounderAsker={question.isFounderAuthor}
                participants={participants}
                replyCount={question.replyCount}
                onCollapse={() => setExpanded(false)}
                canFollow={canFollowAsker}
                isFollowing={isFollowingAsker}
                onToggleFollow={() => { void onToggleFollow() }}
                isFollowPending={isFollowPending}
            />

            <div className="flex flex-col gap-4">
                {/* the question itself, as the first bubble of the conversation */}
                <div className={cn("flex w-full", isMineQuestion ? "justify-end" : "justify-start")}>
                    <div className={cn("flex min-w-0 max-w-[92%] flex-col gap-1", isMineQuestion && "items-end")}>
                        <div className="flex flex-wrap items-center gap-2 px-1 text-xs text-muted">
                            <span className="font-medium text-foreground">{questionName}</span>
                            {question.isFounderAuthor ? (
                                <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                                    <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    {t("courseQa.founderBadge")}
                                </span>
                            ) : null}
                            {question.isPinned ? (
                                <span className="inline-flex items-center gap-1 text-accent-soft-foreground">
                                    <PushPinIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    {t("courseQa.pinned")}
                                </span>
                            ) : null}
                            <span>{getTimeAgoLabel(getTimeAgoMessage(question.createdAt), t)}</span>
                        </div>

                        <ChatBubble role={isMineQuestion ? "user" : "assistant"}>
                            <MarkdownContent markdown={question.body} density="compact" flow="embedded" />
                        </ChatBubble>

                        {/* lesson-funnel tag (course content) + answered/unanswered status */}
                        <div className={cn("flex flex-wrap items-center gap-2 px-1", isMineQuestion && "flex-row-reverse")}>
                            {question.contentId ? (
                                <Link onPress={goToLesson} className="cursor-pointer no-underline">
                                    <Chip
                                        size="sm"
                                        variant="soft"
                                        className="bg-default text-muted transition-colors hover:text-foreground"
                                    >
                                        {t("courseQa.lessonTag", { title: question.contentTitle ?? "" })}
                                    </Chip>
                                </Link>
                            ) : (
                                <Chip size="sm" variant="soft" className="bg-default text-muted">
                                    {t("courseQa.generalTag")}
                                </Chip>
                            )}
                            {question.replyCount > 0 ? (
                                <Chip size="sm" variant="soft" color="success" className="gap-1">
                                    {question.answeredByFounder ? (
                                        <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                                    ) : null}
                                    {question.answeredByFounder
                                        ? t("courseQa.answeredByFounder")
                                        : t("courseQa.statusAnswered")}
                                </Chip>
                            ) : (
                                <Chip size="sm" variant="soft" className="bg-default text-muted">
                                    {t("courseQa.statusUnanswered")}
                                </Chip>
                            )}
                            {/* react to the question itself (6-emotion) ΓÇö the question is a comment */}
                            <ReactionBar
                                summary={question.reactions}
                                onReact={(type) => { void onReactQuestion(type) }}
                            />
                        </div>
                    </div>
                </div>

                {/* answers ΓÇö each a chat bubble; own messages right, peers + founder left */}
                {isLoadingAnswers && answers.length === 0 ? (
                    <div className="flex justify-center py-2">
                        <Spinner size="sm" />
                    </div>
                ) : (
                    answers.map((answer) => (
                        <QaMessageBubble
                            key={answer.id}
                            comment={answer}
                            currentUserId={currentUserId}
                            currentUser={currentUser}
                            repliesByParent={answerRepliesByParent}
                            // only the asker may accept, and only a DIRECT answer (this map)
                            canAccept={isMineQuestion}
                            onAcceptAnswer={(commentId, accepted) => { void onAcceptAnswer(commentId, accepted) }}
                            onReply={(parentId, body) => { void onReply(parentId, body) }}
                            onEdit={(commentId, body) => { void onEdit(commentId, body) }}
                            onDelete={(commentId) => { void onDelete(commentId) }}
                            onReactComment={(commentId, type) => { void onReactComment(commentId, type) }}
                            onLoadReplies={onLoadReplies}
                        />
                    ))
                )}
            </div>

            {/* bottom composer ΓÇö add an answer as a chat message */}
            <Composer
                value={answerDraft}
                onChange={setAnswerDraft}
                onSubmit={() => { void submitAnswer() }}
                isSubmitting={isPostingAnswer}
                avatarSrc={currentUser?.avatar}
                placeholder={t("discussion.replyPlaceholder")}
                submitLabel={t("discussion.reply")}
            />
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { RatingBar, type RatingOption } from "@/components/blocks/buttons/RatingBar"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `QuizRecapList` ΓÇö the run is over: go back over what you answered and say how well
 * you actually knew each one. This learner-supplied grade is not the run's verdict ΓÇö
 * a card can be marked correct yet be one the learner wants back tomorrow (the
 * `CorrectButShaky` case), which the spaced-repetition schedule needs. Already-graded
 * cards keep their rating bar ΓÇö nothing locks after a tap, so a changed mind still
 * counts. Card count and which are rated are states of one shape; finishing changes
 * only the counter line.
 */

/** One answered card in the recap. */
export interface QuizRecapCard {
    /** Stable React key. */
    key: string
    /** The question, as authored markdown. */
    question: string
    /** The expected answer, as authored markdown. */
    expectedAnswer: string
    /** What the learner typed during the run. */
    givenAnswer?: string
    /** How the run judged it. */
    wasCorrect: boolean
    /** The learner's own recall grade, once they have given one. */
    rating?: number
}

interface QuizRecapListOwnProps {
    /** Recall grades offered per card. */
    ratingOptions: Array<RatingOption>
    /** Fired with the card key and the grade the learner picked. */
    onRate: (cardKey: string, grade: number) => void
    /** Accessible name for each card's rating group, localized by the caller. */
    ratingAriaLabel: string
    /** Card count to shimmer while `isSkeleton` (no real `cards` yet). Defaults to `3`. */
    skeletonCount?: number
}

/**
 * Props for {@link QuizRecapList}. `cards` is REQUIRED unless `isSkeleton`
 * (┬º12b) ΓÇö a shimmer recap has no real cards to show yet.
 */
export type QuizRecapListProps = QuizRecapListOwnProps &
    (
        | { isSkeleton: true; cards?: Array<QuizRecapCard> }
        | { isSkeleton?: false; cards: Array<QuizRecapCard> }
    )

/**
 * One recap card's content ΓÇö verdict chip, question, given/expected answers,
 * rating bar. Extracted to a helper (rather than hoisted to a const) because
 * it depends on the loop variable `card` from the `.map()` that calls it.
 */
const recapCardBody = (
    card: QuizRecapCard,
    ratingOptions: Array<RatingOption>,
    onRate: (cardKey: string, grade: number) => void,
    ratingAriaLabel: string,
): ReactNode => (
    <StackV
        gap={6}
        principle="block-boundary"
        explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
        items={[
            () => (
                <StackH
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center"

                    items={[
                        () => (
                            <Chip
                                tone={card.wasCorrect ? "success" : "danger"}
                                text={card.wasCorrect ? "Correct" : "Incorrect"}

                            />
                        ),
                    ]}
                />
            ),
            () => (
                <MarkdownContent
                    source={card.question}
                    measure="compact"

                />
            ),
            ...(card.givenAnswer != null ? [() => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Your answer" />,
                        () => <Typography size="sm" text={card.givenAnswer} />,
                    ]}
                />
            )] : []),
            () => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Expected answer" />,
                        () => (
                            <MarkdownContent
                                source={card.expectedAnswer}
                                measure="compact"

                            />
                        ),
                    ]}
                />
            ),
            // Stays put after a tap. A learner going back over a run changes
            // their mind, and removing the control would make the first tap
            // final without ever saying so.
            () => (
                <RatingBar
                    options={ratingOptions}
                    onRate={(grade) => onRate(card.key, grade)}
                    ariaLabel={ratingAriaLabel}


                />
            ),
        ]}
    />
)

/**
 * The end-of-run recap. See the file header for the full contract.
 *
 * @param props - {@link QuizRecapListProps}
 */
const QuizRecapList = ({
    cards,
    ratingOptions,
    onRate,
    ratingAriaLabel,
    isSkeleton = false,
    skeletonCount = 3,
}: QuizRecapListProps) => {
    if (isSkeleton) {
        const skeletonCardBody = (
            <>
                <Skeleton className="h-5 w-16 rounded-full" />
                <Skeleton className="h-4 w-full rounded" />
                <Skeleton className="h-4 w-2/3 rounded" />
            </>
        )
        const skeletonCards = Array.from({ length: skeletonCount }, (_unused, index) => (
            <SurfaceCard
                key={index}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => skeletonCardBody]} />}
            />
        ))
        const loadingBody = (
            <>
                <Skeleton className="h-3.5 w-40 rounded" />
                {skeletonCards}
            </>
        )
        return (
            <div>
                <StackV gap={6} isSkeleton={isSkeleton} items={[() => loadingBody]} />
            </div>
        )
    }
    const unrated = (cards ?? []).filter((card) => card.rating == null).length

    const recapCards = (cards ?? []).map((card) => (
        <SurfaceCard
            key={card.key}

            body={() => recapCardBody(card, ratingOptions, onRate, ratingAriaLabel)}
        />
    ))

    const recapBody = (
        <>
            {/* Counted, not celebrated. The recap is work; the learner is here to finish
                it, not to be congratulated for starting it. */}
            <Typography
                size="sm"
                color="muted"
                text={unrated > 0 ? `${unrated}/${(cards ?? []).length} cards left to self-grade` : `All ${(cards ?? []).length} cards self-graded`}

            />
            {recapCards}
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => recapBody]} />
        </div>
    )
}

export { QuizRecapList }

import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Button as HeroButton, Popover as HeroPopover } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"
import { ReactionPicker } from "@/components/atoms/feedback/ReactionPicker"
import { StackH } from "@/components/frames/Stack"
import { ReactionGlyph } from "./ReactionGlyph"
import { REACTION_BY_TYPE, type ReactionButtonProps, type ReactionType } from "./types"

export type { ReactionType, ReactionCount, ReactionButtonProps } from "./types"

/**
 * BLOCK ΓÇö `ReactionButton`: the Facebook-style six-emotion reaction control ΓÇö
 * pill trigger + Popover picker + compact summary. Shared verbatim between
 * `ContentReaction` (the lesson-level reaction) and each comment row in
 * `ContentDiscussion`'s thread ΓÇö the SAME control real `src`'s `ReactionBar`
 * is, reused between `InteractionBar` and `CommentItem`.
 *
 * LEAF by STRUCTURE (┬º14d.2). Which emotion is picked and whether the
 * summary is empty keep the same two-part shape => states. The caller
 * flipping `isSkeleton` is its own leaf.
 */

/**
 * The reaction trigger + picker + summary. See the file header for the full contract.
 *
 * @param props - {@link ReactionButtonProps}
 */
const ReactionButton = ({
    myReaction = null,
    counts = [],
    onReact,
    isPending = false,
    isSkeleton = false,
}: ReactionButtonProps) => {
    // controlled so the popover closes as soon as an emotion is picked ΓÇö mirrors real ReactionBar
    const [isOpen, setIsOpen] = useState(false)

    const total = counts.reduce((sum, entry) => sum + entry.count, 0)
    // busiest emotions first, top 3 ΓÇö same cap real ReactionBar uses for the stacked summary
    const topReactions = counts
        .slice()
        .sort((prev, next) => next.count - prev.count)
        .slice(0, 3)
        .map((entry) => REACTION_BY_TYPE[entry.type])

    const onPick = (type: ReactionType) => {
        setIsOpen(false)
        onReact(myReaction === type ? null : type)
    }

    if (isSkeleton) {
        return <span className="inline-block h-8 w-28 animate-pulse rounded-full bg-default" />
    }

    // compact summary: stacked top emojis + total ΓÇö dropped entirely at zero
    const summaryRow = total > 0 ? (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <span className="flex items-center -space-x-1">
                        {topReactions.map((reaction) => (
                            <ReactionGlyph key={reaction.type} type={reaction.type} size="sm" />
                        ))}
                    </span>
                ),
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" text={String(total)} />,
            ]}
        />
    ) : null

    const triggerAndSummary = (
        <>
            {/* trigger: opens the 6-emotion picker; shows the viewer's own pick once set */}
            <HeroPopover isOpen={isOpen} onOpenChange={setIsOpen}>
                <HeroPopover.Trigger>
                    <HeroButton
                        variant="tertiary"
                        isDisabled={isPending}
                        className="rounded-full"

                    >
                        <ReactionGlyph type={myReaction ?? "like"} size="sm" />
                        <span className="text-sm">
                            {myReaction ? REACTION_BY_TYPE[myReaction].label : "React"}
                        </span>
                    </HeroButton>
                </HeroPopover.Trigger>
                {/* TODO(atom): heavy skin-shape (rounded-full + px-2 py-1 pill) ΓÇö a frame cannot own it,
 wrap with a hand-set data-principle for now. `className` sits on `HeroPopover.Content`
 itself (the vendor's OWN rendered surface, react-aria `Popover`), not a raw <div>
 we author, so `Box` can't wrap it (moving the shape down onto an inner wrapping
 Box would leave the real popover surface with its default non-pill radius showing
 behind it ΓÇö a visible shape regression). `data-principle` on `Content` directly is
 type-safe (forwarded through `DOMAttributes`), so tagged in place instead. Needs a
 dedicated pill-popover atom/composite to own this shape. Same declared shape
 as `QaReactionBar.tsx`'s trigger.
 inset-exception: pill geometry, the same px-2 py-1 HeroUI ships in chip.css. */}
                <HeroPopover.Content data-principle="pill-pad" className="overflow-visible rounded-full px-2 py-1">
                    <ReactionPicker
                        items={Object.values(REACTION_BY_TYPE).map((reaction) => ({ key: reaction.type, imgSrc: `/reactions/${reaction.type}.svg`, label: reaction.label }))}
                        activeKey={myReaction}
                        onSelect={(key) => onPick(key as ReactionType)}
                    />
                </HeroPopover.Content>
            </HeroPopover>

            {summaryRow}
        </>
    )

    return (
        <StackH gap={3} principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center" isSkeleton={isSkeleton} items={[() => triggerAndSummary]}  />
    )
}

