"use client"

import React from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    CaretLeftIcon,
    CaretRightIcon,
} from "@phosphor-icons/react"
import {
    useLessonNavigation,
} from "../hooks/useLessonNavigation"
import { GroupPressableCard } from "@/components/blocks/cards/GroupPressableCard"
import type { GroupPressableCardItem } from "@/components/blocks/cards/GroupPressableCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/** Props for {@link LessonPager}. */
export type LessonPagerProps = Record<string, never>
/**
 * Previous / next lesson pager shown at the foot of the reader: two navigation
 * cards that move through the course in its linear order (the prev card aligns
 * left, the next card right). Self-contained ΓÇö reads the linear position from
 * {@link useLessonNavigation} and renders nothing once the outline has resolved
 * and neither neighbour exists (a skeleton mirrors the pair while it's still
 * resolving ΓÇö 2026-07-12: the outline used to be indistinguishable from "no
 * neighbours" here, so the pager popped in below the already-rendered lesson
 * body instead of being covered by any loading state).
 *
 * @param props - {@link LessonPager}
 */
export const LessonPager = () => {
    const t = useTranslations()
    const { previous, next, isLoading } = useLessonNavigation()

    if (isLoading) {
        return (
            <div>
                {/*
                  Mirrors the resolved pager below, which reflows on its CONTAINER
                  (`GroupPressableCard columns={{base:1, sm:2}}`). The skeleton must
                  split on the SAME axis at the SAME step ΓÇö a viewport `sm:` here
                  would show one column while the real pair renders two (or vice
                  versa in a narrow slot), i.e. a jump at exactly the moment the
                  skeleton is supposed to prevent one.
                */}
                <div className="@container">
                    <div className="grid grid-cols-1 gap-3 @sm:grid-cols-2">
                        <div className="flex items-center gap-2 rounded-3xl bg-surface px-4 py-3">
                            <Skeleton className="size-5 shrink-0 rounded" />
                            <div className="flex min-w-0 flex-1 flex-col gap-1">
                                <Skeleton.Typography type="body-xs" width="1/3" />
                                <Skeleton.Typography type="body-sm" width="3/4" />
                            </div>
                        </div>
                        <div className="flex items-center justify-end gap-2 rounded-3xl bg-surface px-4 py-3">
                            <div className="flex min-w-0 flex-1 flex-col items-end gap-1">
                                <Skeleton.Typography type="body-xs" width="1/3" />
                                <Skeleton.Typography type="body-sm" width="3/4" />
                            </div>
                            <Skeleton className="size-5 shrink-0 rounded" />
                        </div>
                    </div>
                </div>
            </div>
        )
    }

    if (!previous && !next) {
        return null
    }

    const items: Array<GroupPressableCardItem> = []
    if (previous) {
        items.push({
            key: "previous",
            href: previous.href,
            content: () => (
                <div className="flex items-center gap-2">
                    <CaretLeftIcon aria-hidden focusable="false" weight="bold" className="size-4 shrink-0 text-muted" />
                    <div className="flex min-w-0 flex-col gap-0">
                        <Typography type="body-xs" color="muted">
                            {t("content.prevLesson")}
                        </Typography>
                        <Typography type="body-sm" weight="medium" className="line-clamp-2">
                            {previous.title}
                        </Typography>
                    </div>
                </div>
            ),
        })
    }
    if (next) {
        items.push({
            key: "next",
            href: next.href,
            // Pin right exactly where the grid actually HAS two columns, so this
            // must be scoped on the SAME axis the group splits on ΓÇö a CONTAINER
            // query (`@sm`), not the viewport (`sm`). Unqualified `col-start-2`
            // would also apply at the 1-column step, forcing an implicit second
            // column that content-sizes down to ~30px and drags this card up beside
            // the previous one; viewport-scoped `sm:` would miss in both directions
            // (narrow slot in a wide window still splits, and vice versa).
            className: "@sm:col-start-2",
            content: () => (
                <div className="flex items-center justify-end gap-2">
                    <div className="flex min-w-0 flex-col gap-0">
                        <Typography type="body-xs" color="muted" align="end">
                            {t("content.nextLesson")}
                        </Typography>
                        <Typography type="body-sm" weight="medium" align="end" className="line-clamp-2">
                            {next.title}
                        </Typography>
                    </div>
                    <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4 shrink-0 text-muted" />
                </div>
            ),
        })
    }

    return (
        <div>
            <GroupPressableCard
                ariaLabel={t("content.pagerAria")}
                columns={{ base: 1, sm: 2 }}
                items={items}
            />
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import { useTheme } from "next-themes"
import { SandpackPanel } from "@/components/blocks/code/SandpackPanel"
import { CodeBodySkeleton } from "../CodeBodySkeleton"
import type { SandpackFiles } from "@codesandbox/sandpack-react"
import { useAppSelector } from "@/redux/hooks"
import { useQueryContentSwr } from "@/hooks/swr/api/graphql/queries/useQueryContentSwr"
import { useRepoSandpackFiles } from "@/hooks/useRepoSandpackFiles"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"

/**
 * Tailwind v4 theme registered at runtime in the preview iframe. `@tailwindcss/browser`
 * uses the DEFAULT config (no HeroUI colors), and heroui.min.css does not ship
 * `bg-background` / `text-foreground` / `default-*` utilities ΓÇö so we register them
 * here as a `<style type="text/tailwindcss">`. `@custom-variant dark` makes the
 * `.dark` class drive every token (page bg, text, hover) for both light and dark.
 */
const THEME_TAILWINDCSS = `@custom-variant dark (&:where(.dark, .dark *));
@theme {
  --font-sans: "Inter", ui-sans-serif, system-ui, sans-serif;
  --color-background: var(--sb-bg);
  --color-foreground: var(--sb-fg);
  --color-muted: var(--sb-muted);
  --color-border: var(--sb-border);
  --color-content1: var(--sb-content1);
  --color-default-50: var(--sb-d50);
  --color-default-100: var(--sb-d100);
  --color-default-200: var(--sb-d200);
  --color-default-300: var(--sb-d300);
  --color-default-400: var(--sb-muted);
  --color-default-500: var(--sb-muted);
  --color-default-600: var(--sb-d600);
  --color-default-700: var(--sb-d700);
  --color-accent: var(--sb-accent);
  --color-primary: var(--sb-primary);
  --color-focus: var(--sb-primary);
  --color-danger: var(--sb-danger);
  --color-success: var(--sb-success);
  --color-warning: var(--sb-warning);
}
:root {
  --sb-bg: oklch(97.02% 0.0033 185.90); --sb-fg: #18181b; --sb-muted: #71717a; --sb-border: #e4e4e7;
  --sb-d50: #fafafa; --sb-d100: #f4f4f5; --sb-d200: #e4e4e7; --sb-d300: #d4d4d8; --sb-d600: #52525b; --sb-d700: #3f3f46;
  --sb-content1: #ffffff; --sb-accent: #0d9488; --sb-primary: #006fee; --sb-danger: #f31260; --sb-success: #17c964; --sb-warning: #f5a524;
  /* raw semantic vars (no color- prefix) so the lesson's globals.css var(--border)/var(--background) resolve */
  --background: var(--sb-bg); --foreground: var(--sb-fg); --border: var(--sb-border); --muted: var(--sb-muted);
  --default-100: var(--sb-d100); --default-200: var(--sb-d200); --content1: var(--sb-content1);
}
.dark {
  --sb-bg: oklch(12.00% 0.0033 185.90); --sb-fg: #fafafa; --sb-muted: #a1a1aa; --sb-border: #27272a;
  --sb-d50: oklch(16.00% 0.0033 185.90); --sb-d100: oklch(20.00% 0.0033 185.90); --sb-d200: #3f3f46; --sb-d300: #52525b; --sb-d600: #a1a1aa; --sb-d700: #d4d4d8;
  --sb-content1: oklch(20.00% 0.0033 185.90); --sb-accent: #2dd4bf; --sb-primary: #006fee; --sb-danger: #f31260; --sb-success: #17c964; --sb-warning: #f5a524;
}`

/**
 * Bridges the Sandpack template entry (/App.tsx, imported as ../App) to the real
 * /src/App. Injects the Tailwind theme + toggles the platform light/dark mode on
 * the preview iframe's <html>.
 */
const buildAppBridge = (isDark: boolean, globalsCssImport: string): string => `import { useEffect } from "react"
import App from "./src/App"
${globalsCssImport}

// Force ?sandbox=1 into the URL before App's first render. Sandpack's startRoute
// query does not reliably reach window.location.search inside the preview iframe,
// so multi-client lessons (websocket: chat/presence/reconnection) would otherwise
// fall back to the single-client Local view and lose their User A / User B tabs.
// This runs at module eval ΓÇö before App's useState reads window.location.search.
if (typeof window !== "undefined" && !new URLSearchParams(window.location.search).has("sandbox")) {
    window.history.replaceState(null, "", window.location.pathname + "?sandbox=1" + window.location.hash)
}

export default function SandboxRoot() {
    useEffect(() => {
        document.documentElement.classList.toggle("dark", ${isDark})
        // load Inter (the font heroui.com uses) so the preview matches the docs
        if (!document.getElementById("sb-font")) {
            const link = document.createElement("link")
            link.id = "sb-font"
            link.rel = "stylesheet"
            link.href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap"
            document.head.appendChild(link)
        }
        if (!document.getElementById("sb-theme")) {
            const style = document.createElement("style")
            style.id = "sb-theme"
            style.setAttribute("type", "text/tailwindcss")
            style.textContent = ${JSON.stringify(THEME_TAILWINDCSS)}
            document.head.appendChild(style)
        }
    }, [])
    return <App />
}
`

/**
 * Rewrites a lesson source file so it runs inside Sandpack's bundler:
 *  - `import.meta.env.VITE_API_BASE` ΓåÆ the session-scoped mock URL literal
 *  - any other `import.meta.env.X` ΓåÆ "" (bundler can't evaluate import.meta)
 *  - `import.meta.hot...` ΓåÆ undefined (HMR not available)
 *  - strips Tailwind/HeroUI @import directives (loaded via CDN instead)
 */
const rewriteForSandpack = (code: string, mockApiBase: string): string =>
    code
        .replace(/import\.meta\.env\.VITE_API_BASE/g, JSON.stringify(mockApiBase))
        .replace(/import\.meta\.env\.\w+/g, "\"\"")
        .replace(/import\.meta\.env/g, "({})")
        .replace(/import\.meta\.hot[^\n]*/g, "undefined")
        .replace(/@import\s+["']tailwindcss["'];?/g, "")
        .replace(/@import\s+["']@heroui\/styles["'];?/g, "")

/**
 * Sandbox tab body ΓÇö runs the lesson's frontend live in Sandpack against a
 * session-isolated mock API served by the standalone mock app. Always light
 * theme (dark mode is intentionally ignored here).
 *
 * Flow:
 * 1. A random sessionId is generated client-side (the mock app lazily seeds on
 *    first request ΓÇö no handshake needed).
 * 2. The lesson source is fetched from GitHub (cached by repo URL).
 * 3. Every file's `import.meta.env.VITE_API_BASE` is overridden to the mock URL
 *    `<mockHost>/mocks/<module>/<lesson>/sessions/<sessionId>` ΓÇö the cloned source
 *    still falls back to `http://localhost:3000` for local dev.
 */
export const SandboxBody = () => {
    const queryContentSwr = useQueryContentSwr()
    const content = useAppSelector((state) => state.content.entity)
    // editor chrome follows the platform theme; the preview app stays light
    const { resolvedTheme } = useTheme()
    const isDark = resolvedTheme !== "light"

    // host of the standalone mock app (e.g. http://localhost:3002 ΓÇö no /api prefix)
    const mockApiHost = process.env.NEXT_PUBLIC_MOCK_API_BASE_URL ?? ""
    // lesson path on that host (e.g. /mocks/4-server-state.../0-usequery...)
    const lessonPath = content?.backendUrl ?? null

    // fresh isolated session id, stable for this lesson's component lifetime
    const sessionId = useMemo(
        () => (typeof crypto !== "undefined" ? crypto.randomUUID() : `${Date.now()}`),
        [content?.id],
    )

    const { files: githubFiles, dependencies, isLoading: githubLoading } = useRepoSandpackFiles(
        content?.id,
        content?.githubBaseUrl,
        content?.githubDir,
        content?.isPremium,
    )

    const contentReady = !queryContentSwr.isLoading && !!queryContentSwr.data && !queryContentSwr.error
    // first load (content + repo files) ΓåÆ mirror the code-shaped skeleton via AsyncContent
    const isLoading = !contentReady || githubLoading

    // full session-scoped mock URL the lesson's VITE_API_BASE will point at
    const mockApiBase = lessonPath
        ? `${mockApiHost}${lessonPath}/sessions/${sessionId}`
        : ""

    // rewrite every fetched file's env reference to the live mock URL
    const rewrittenFiles: SandpackFiles = {}
    for (const [path, file] of Object.entries(githubFiles ?? {})) {
        const code = typeof file === "string" ? file : file.code
        rewrittenFiles[path] = { code: rewriteForSandpack(code, mockApiBase) }
    }

    // synthetic stubs: bridge the template entry (+ theme sync) and no-op the
    // vite config the bundler can't run. Tailwind v4 + HeroUI load via
    // SandpackProvider externalResources (not index.html ΓÇö Sandpack ignores tags there).
    // The bridge imports App directly (bypassing main.tsx), so the lesson's
    // globals.css ΓÇö normally imported by main.tsx ΓÇö would never load, dropping
    // its body reset and custom rules (e.g. the `.input` border). Re-import it
    // from the bridge when present (path-safe: only if the lesson ships one).
    const globalsKey = Object.keys(rewrittenFiles).find((p) => p.endsWith("/globals.css"))
    const globalsCssImport = globalsKey ? `import ".${globalsKey}"` : ""

    const stubs: SandpackFiles = {
        "/App.tsx": { code: buildAppBridge(isDark, globalsCssImport) },
        "/vite.config.ts": { code: "// vite config omitted in sandbox" },
    }

    const files: SandpackFiles = { ...stubs, ...rewrittenFiles }

    // thin, rounded, theme-aware scrollbars for the editor/file-tree (default ones look crude)
    const thumb = isDark ? "rgba(255,255,255,0.16)" : "rgba(0,0,0,0.16)"
    const thumbHover = isDark ? "rgba(255,255,255,0.28)" : "rgba(0,0,0,0.28)"

    const body = (
        <div className="sb-scroll mt-3">
            <style>{`
                .sb-scroll *::-webkit-scrollbar { width: 8px; height: 8px; }
                .sb-scroll *::-webkit-scrollbar-track { background: transparent; }
                .sb-scroll *::-webkit-scrollbar-thumb { background: ${thumb}; border-radius: 9999px; border: 2px solid transparent; background-clip: content-box; }
                .sb-scroll *::-webkit-scrollbar-thumb:hover { background: ${thumbHover}; background-clip: content-box; }
                .sb-scroll *::-webkit-scrollbar-corner { background: transparent; }
                .sb-scroll * { scrollbar-width: thin; scrollbar-color: ${thumb} transparent; }
            `}</style>
            {/* key on theme forces a full re-mount (fresh preview iframe) when the
                platform light/dark toggles, so the bridge re-runs and the sandbox UI
                reloads with the new theme instead of keeping the stale dark class. */}
            <SandpackPanel
                key={isDark ? "sandbox-dark" : "sandbox-light"}
                files={files}
                dependencies={dependencies}
                isDark={isDark}
            />
        </div>
    )

    return (
        <AsyncContent
            isLoading={isLoading}
            skeleton={<CodeBodySkeleton />}
        >
            {body}
        </AsyncContent>
    )
}

"use client"

import React, { useCallback, useMemo } from "react"
import { Typography } from "@heroui/react"
import {
    GithubLogoIcon,
    PlayIcon,
} from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import {
    buildMilestoneTaskProgressLookup,
    isPersonalProjectTaskActionUnlocked,
} from "@/components/utils/task-lookup"
import { PersonalProjectDashboardSkeleton } from "./PersonalProjectDashboardSkeleton"
import { TaskBreadcrumb } from "../TaskBreadcrumb"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setSelectedTaskId } from "@/redux/slices/milestone"
import { useQueryMilestonesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestonesSwr"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { pathConfig } from "@/resources/path"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { ContinueCard } from "@/components/blocks/cards/ContinueCard"
import { SurfaceCardHeader } from "@/components/composites/cards/SurfaceCard/surface-card-header"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Chip } from "@/components/atoms/chips/Chip"
import { Grid } from "@/components/frames/Grid"
import { StackV } from "@/components/frames/Stack"
import type { MilestoneEntity } from "@/modules/types/entities/milestone"

/** Props for {@link PersonalProjectDashboard}. */
export type PersonalProjectDashboardProps = Record<string, never>
/** github.com URL ΓåÆ `owner/repo` (drops scheme + trailing .git) for a compact label. */
const toRepoLabel = (url: string): string =>
    url
        .trim()
        .replace(/^https?:\/\/(www\.)?github\.com\//i, "")
        .replace(/\.git$/i, "")
        .replace(/\/$/, "")

/**
 * Personal-project landing DASHBOARD ΓÇö shown by {@link
 * import("../PersonalProjectWorkspace").PersonalProjectWorkspace} when the URL has
 * no `tasks/[id]` (overview instead of an empty column).
 *
 * Mirrors the course-content home (`CourseContents`) layout so the two learn home
 * surfaces read consistently: TIER-1 breadcrumb ΓåÆ TIER-2 header (project title +
 * description + a GitHub status chip) ΓåÆ TIER-3 a {@link ContinueCard} `hero` for
 * the next task (chip "Continue") + progress meter, above the keep-going path =
 * current milestone tasks as {@link ContinueCard} `item` cards (with per-card
 * "Continue >" CTA) in a labeled section grid. The milestone LIST
 * for the whole project lives in the left rail ΓÇö the body only surfaces "where
 * you are + what's next". Every value is grounded in real BE fields
 * (`milestoneTaskProgress`, enrollment github).
 *
 * @param props - {@link PersonalProjectDashboardProps}
 */
export const PersonalProjectDashboard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const milestonesSwr = useQueryMilestonesSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    // github connection truth lives on the enrollment (the github store is only seeded inside
    // the task panel, which isn't mounted on the dashboard) ΓÇö read it straight from redux
    const enrollment = useAppSelector((state) => state.user.enrollment)
    const githubUrl = enrollment?.personalProjectGithubUrl ?? ""
    const githubBranch = enrollment?.personalProjectGithubBranch ?? ""

    const milestones = useMemo(
        () => [...milestoneEntities].sort((prev, next) => prev.sortIndex - next.sortIndex),
        [milestoneEntities],
    )
    const completionTasks = progressSwr.data?.milestoneTaskProgress?.data?.completionTasks
    const progressMap = useMemo(
        () => buildMilestoneTaskProgressLookup(completionTasks),
        [completionTasks],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    /** The next task to work on, plus the milestone that owns it (for the continue block). */
    const currentTask = useMemo(() => {
        if (!currentTaskId) {
            return undefined
        }
        for (const milestone of milestones) {
            const task = (milestone.tasks ?? []).find((entity) => entity.id === currentTaskId)
            if (task) {
                return task
            }
        }
        return undefined
    }, [milestones, currentTaskId])

    /** The milestone the learner is in: the one owning the next task, else the first. */
    const currentMilestone = useMemo<MilestoneEntity | undefined>(() => {
        if (currentTaskId) {
            const owning = milestones.find((milestone) =>
                (milestone.tasks ?? []).some((task) => task.id === currentTaskId))
            if (owning) {
                return owning
            }
        }
        return milestones[0]
    }, [milestones, currentTaskId])

    /** Aggregate KPIs across every task in the course (grounded in the progress lookup). */
    const stats = useMemo(() => {
        // total comes from the full milestone tree (every task counts)
        let total = 0
        for (const milestone of milestones) {
            total += (milestone.tasks ?? []).length
        }
        // done / attempts / avg score come from the progress rows (carry lastScore/maxScore)
        let done = 0
        let attempts = 0
        let scoreSum = 0
        let maxSum = 0
        let scored = 0
        for (const item of completionTasks ?? []) {
            attempts += item.numAttempts ?? 0
            if (item.completed) {
                done += 1
                if (typeof item.lastScore === "number") {
                    scoreSum += item.lastScore
                    maxSum += item.maxScore ?? 20
                    scored += 1
                }
            }
        }
        return {
            done,
            total,
            attempts,
            avgScore: scored > 0 ? Math.round(scoreSum / scored) : null,
            avgMax: scored > 0 ? Math.round(maxSum / scored) : 20,
        }
    }, [milestones, completionTasks])

    const isConnected = githubUrl.trim().length > 0
    const avgLabel = stats.avgScore != null ? `${stats.avgScore}/${stats.avgMax}` : "ΓÇö"

    /** Jump into the next task (or the very first one): mirror the rail's select+route. */
    const onContinue = useCallback(() => {
        const taskId = currentTaskId ?? milestones[0]?.tasks?.[0]?.id
        if (!taskId) {
            return
        }
        dispatch(setSelectedTaskId(taskId))
        router.push(
            pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(taskId).build(),
        )
    }, [currentTaskId, milestones, dispatch, router, locale, courseDisplayId])

    /** Open a task from the keep-going path (the locked brief handles its own gate). */
    const onSelectTask = useCallback(
        (taskId: string) => {
            dispatch(setSelectedTaskId(taskId))
            router.push(
                pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(taskId).build(),
            )
        },
        [dispatch, router, locale, courseDisplayId],
    )

    // gate on first load only (cached redux milestones win); brief skeleton while progress lands
    const hasMilestones = milestones.length > 0
    const isLoading = (!hasMilestones && !milestonesSwr.error && (milestonesSwr.isLoading || !milestonesSwr.data))
        || (progressSwr.isLoading && !progressSwr.data)
    const isEmpty = !hasMilestones && !milestonesSwr.isLoading && !!milestonesSwr.data && !milestonesSwr.error

    return (
        <div className={"mx-auto flex w-full max-w-3xl flex-col gap-10"}>
            {/* shared PageHeader: breadcrumb ΓåÆ H3 title ΓåÆ muted desc ΓåÆ github status chip (meta).
                header ΓåÆ content = gap-10 (page-heading debt). */}
            <PageHeader
                breadcrumb={<TaskBreadcrumb />}
                title={t("finalProject.dashboard.title")}
                description={t("finalProject.dashboard.subtitle")}
                meta={(
                    <Chip
                        tone={isConnected ? "success" : "default"}
                        icon={GithubLogoIcon}
                        text={
                            isConnected
                                ? `${toRepoLabel(githubUrl)} ┬╖ ${githubBranch || "main"}`
                                : t("finalProject.dashboard.notConnected")
                        }
                    />
                )}
            />
            {/* content */}
            <AsyncContent
                isLoading={isLoading}
                skeleton={<PersonalProjectDashboardSkeleton />}
                isEmpty={isEmpty}
                emptyContent={{ title: t("finalProject.dashboard.empty") }}
            >
                <div className="flex flex-col gap-6">
                    {/* next task as ContinueCard hero (chip CTA ΓÇö not the faint
                        LabeledCard see-more link), then the honest progress meter. */}
                    <div className="flex flex-col gap-3">
                        {currentTask ? (
                            <ContinueCard
                                variant="hero"
                                icon={() => <PlayIcon weight="fill" />}
                                title={`${currentTask.sortIndex}. ${currentTask.title}`}
                                subtitle={t("finalProject.dashboard.nextTask")}
                                ctaLabel={t("finalProject.dashboard.continue")}
                                onPress={onContinue}
                            />
                        ) : (
                            <Typography type="body" weight="semibold">
                                {t("finalProject.dashboard.allDone")}
                            </Typography>
                        )}
                        <ProgressMeter
                            value={stats.done}
                            max={stats.total || 1}
                            label={t("finalProject.dashboard.completion")}
                            showValue
                        />
                        <Typography type="body-xs" color="muted">
                            {t("finalProject.dashboard.statsLine", {
                                done: stats.done,
                                total: stats.total,
                                attempts: stats.attempts,
                                avg: avgLabel,
                            })}
                        </Typography>
                    </div>

                    {/* keep-going: ContinueCard item grid ΓÇö "Continue >" lives on each
                        card (Storybook Item), not as a soft see-more beside the label. */}
                    {currentMilestone ? (
                        // B37 Decision E: ContinueCard tiles self-frame ΓÇö StackV
                        // label-field replaces LabeledCard frameless around the grid.
                        <StackV
                            gap={3}
                            principle="label-field"
                            explain="Section label above its control is label-field ΓÇö not title-subtitle (no paired title/supporting lines), not name-handle, not icon-text; the label names the surface the way a field label names its control."
                            items={[
                                () => (
                                    <SurfaceCardHeader
                                        label={`${t("finalProject.dashboard.keepGoing")} ┬╖ ${currentMilestone.title}`}
                                    />
                                ),
                                () => (
                                    <Grid
                                        columns={{ base: 1, sm: 2 }}
                                        principle="sibling-stack"
                                        explain="Keep-going task tiles share one section grid ΓÇö not block-boundary, because they stay inside one labeled group."
                                        items={(currentMilestone.tasks ?? []).map((task) => {
                                            const isCompleted = progressMap.get(task.id)?.completed ?? false
                                            const isActive = task.id === currentTaskId
                                            const isLocked = !isPersonalProjectTaskActionUnlocked(
                                                task.id,
                                                progressMap,
                                                currentTaskId,
                                            )
                                            const subtitle = isActive
                                                ? t("finalProject.dashboard.nextTask")
                                                : isCompleted
                                                    ? t("finalProject.dashboard.taskDone")
                                                    : isLocked
                                                        ? t("finalProject.dashboard.statLocked")
                                                        : t("finalProject.dashboard.taskTodo")
                                            return {
                                                key: task.id,
                                                content: () => (
                                                    <ContinueCard
                                                        variant="item"
                                                        title={`${task.sortIndex}. ${task.title}`}
                                                        subtitle={subtitle}
                                                        ctaLabel={t("finalProject.dashboard.continue")}
                                                        onPress={() => onSelectTask(task.id)}
                                                    />
                                                ),
                                            }
                                        })}
                                    />
                                ),
                            ]}
                        />
                    ) : null}
                </div>
            </AsyncContent>
        </div>
    )
}

"use client"

import { SparkleIcon } from "@phosphor-icons/react"
import React, { useCallback, useMemo } from "react"
import { Button, Spinner } from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    usePathname,
    useRouter,
} from "next/navigation"
import { AIProcessingText } from "@/components/blocks/learn/AIProcessingText"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"
import { usePersonalProjectTaskAttemptsDrawerOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { useQueryUserPersonalTaskAttemptsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserPersonalTaskAttemptsSwr"
import { useMutateSyncPersonalProjectGithubSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSyncPersonalProjectGithubSwr"
import { useMutateSyncPersonalProjectGithubBranchSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSyncPersonalProjectGithubBranchSwr"
import { useAppSelector } from "@/redux/hooks"
import { buildMilestoneTaskProgressLookup, isPersonalProjectTaskActionUnlocked } from "@/components/utils/task-lookup"

/** Props for {@link TaskActions}. */
export type TaskActionsProps = Record<string, never>
/**
 * Action row for the task panel: evaluate, feedback, attempts, plus AI status.
 *
 * Self-contained: reads all state from redux/SWR/zustand hooks ΓÇö no callback or
 * flag props needed. Dispatches the submit/open actions directly.
 * @param props - optional className for the root element
 */
export const TaskActions = () => {
    const t = useTranslations()
    const router = useRouter()
    const pathname = usePathname()
    const reviewGithubForm = usePersonalProjectGithubForm()
    const syncGithubSwr = useMutateSyncPersonalProjectGithubSwr()
    const syncBranchSwr = useMutateSyncPersonalProjectGithubBranchSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const personalProjectAttemptsDrawer = usePersonalProjectTaskAttemptsDrawerOverlayState()
    const attemptsSwr = useQueryUserPersonalTaskAttemptsSwr()

    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const milestoneTaskIdToJobId = useAppSelector((state) => state.milestone.milestoneTaskIdToJobId)
    const jobStatusByJobId = useAppSelector((state) => state.socketIo.jobStatusByJobId)

    const attemptRows = useMemo(
        () => attemptsSwr.data?.data ?? [],
        [attemptsSwr.data?.data],
    )
    const hasReviewAttempts = attemptRows.length > 0

    const reviewJobId = selectedTaskId ? milestoneTaskIdToJobId[selectedTaskId] : undefined
    const reviewJobEnvelope = reviewJobId ? jobStatusByJobId[reviewJobId] : undefined
    const reviewJobStatus = reviewJobEnvelope?.data?.status
    const reviewJobError = reviewJobEnvelope?.data?.error

    const progressLookup = useMemo(
        () => buildMilestoneTaskProgressLookup(
            progressSwr.data?.milestoneTaskProgress?.data?.completionTasks,
        ),
        [progressSwr.data],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    const isActionUnlocked = useMemo(
        () => {
            if (!selectedTaskId) {
                return true
            }
            if (progressSwr.isLoading) {
                return true
            }
            return isPersonalProjectTaskActionUnlocked(
                selectedTaskId,
                progressLookup,
                currentTaskId,
            )
        },
        [
            selectedTaskId,
            progressLookup,
            currentTaskId,
            progressSwr.isLoading,
        ],
    )

    const isEvaluateDisabled = useMemo(
        () => !isActionUnlocked
            || reviewGithubForm.isSubmitting
            || attemptsSwr.isLoading
            || syncGithubSwr.isMutating
            || syncBranchSwr.isMutating,
        [
            isActionUnlocked,
            reviewGithubForm.isSubmitting,
            attemptsSwr.isLoading,
            syncGithubSwr.isMutating,
            syncBranchSwr.isMutating,
        ],
    )

    const isEvaluatePending = useMemo(
        () => reviewGithubForm.isSubmitting
            || (
                Boolean(reviewJobId)
                && (
                    reviewJobStatus === JobStatus.Processing
                    || reviewJobStatus === JobStatus.Queued
                )
            ),
        [
            reviewGithubForm.isSubmitting,
            reviewJobId,
            reviewJobStatus,
        ],
    )

    const areSecondaryDisabled = !isActionUnlocked || !hasReviewAttempts

    const showAiProcessing =
        reviewGithubForm.isSubmitting
        || Boolean(reviewJobId)

    const aiJobStatus: JobStatus = reviewGithubForm.isSubmitting
        ? JobStatus.Processing
        : (reviewJobStatus ?? JobStatus.Processing)

    /** Submit the GitHub review form (triggers AI evaluation). */
    const onEvaluate = useCallback(
        () => {
            void reviewGithubForm.submit()
        },
        [reviewGithubForm],
    )

    /** Go to the dedicated task result page (replaces the old feedback modal). */
    const onOpenFeedbacks = useCallback(
        () => router.push(`${pathname}/result`),
        [router, pathname],
    )

    /** Open the personal project attempts drawer. */
    const onOpenAttempts = useCallback(
        () => personalProjectAttemptsDrawer.setOpen(true),
        [personalProjectAttemptsDrawer],
    )

    return (
        // button row <-> AI processing status = gap-3 (same block), no manual h-* spacer
        <div className={"flex flex-col gap-3"}>
            <div className="flex flex-wrap items-center gap-2">
                <Button
                    size="lg"
                    isDisabled={isEvaluateDisabled}
                    isPending={isEvaluatePending}
                    onPress={onEvaluate}
                >
                    {({ isPending }) => (
                        <>
                            {isPending ? <Spinner color="current" /> : <SparkleIcon className="size-5" />}
                            {hasReviewAttempts
                                ? t("finalProject.page.submitGithub.ctaReEvaluate")
                                : t("finalProject.page.submitGithub.ctaEvaluate")}
                        </>
                    )}
                </Button>
                <Button
                    size="lg"
                    variant="secondary"
                    isDisabled={areSecondaryDisabled}
                    onPress={onOpenFeedbacks}
                >
                    {t("task.openFeedbackDetailsButton")}
                </Button>
                <Button
                    size="lg"
                    variant="secondary"
                    isDisabled={areSecondaryDisabled}
                    onPress={onOpenAttempts}
                >
                    {t("finalProject.page.attemptsDrawer.openListButton")}
                </Button>
            </div>
            {showAiProcessing && (
                <AIProcessingText
                    jobCategory={JobCategory.ReviewTask}
                    jobStatus={aiJobStatus}
                    error={reviewJobError}
                />
            )}
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import { ImplementationCard } from "@/components/blocks/learn/lesson/CodeImplementationBody/ImplementationCard"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link TaskCodeImplementations}. */
export type TaskCodeImplementationsProps = Record<string, never>
/**
 * Implementation guide for a milestone task, shown for the language picked by the
 * top "grading language" selector in {@link PersonalProjectSubmission} ΓÇö a single
 * source of truth for the active language, so this section no longer renders its
 * own language tabs. Reuses the lesson implementation card so the look matches.
 *
 * Self-contained: reads `codeImplementations` from redux task state and `lang` from
 * the github form store.
 * @param props - optional className for the root element
 */
export const TaskCodeImplementations = () => {
    // active grading language lives in the shared github-form store (set by the top selector);
    // read-only here, so `enableSync` stays off (default) and no debounced sync runs
    const { lang } = usePersonalProjectGithubForm()

    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [selectedTaskId, selectedTaskDetail, milestoneEntities])

    const codeImplementations = displayTask?.codeImplementations ?? []

    // pick the guide for the selected language (lang vocab matches: typescript/java/csharp/go)
    const selected = useMemo(
        () => codeImplementations.find(
            (item) => item.lang?.toLowerCase() === lang?.toLowerCase(),
        ),
        [codeImplementations, lang],
    )

    // no guide authored for the selected language ΓåÆ render nothing for this section
    if (!selected) {
        return null
    }

    // own title dropped ΓÇö this section now renders under the parent's shared
    // "task.criteriaTitle" LabeledCard (see personal-project/index.tsx) instead of
    // stacking a second hand-rolled header right under the criteria one.
    return <ImplementationCard item={selected} />
}

