/** Icon + tone per finding severity (drives the accordion item header). */
const SEVERITY_VISUAL: Record<MilestoneSeverity, { Icon: typeof WarningCircleIcon, text: string, rank: number }> = {
    [MilestoneSeverity.High]: { Icon: WarningCircleIcon, text: "text-danger-soft-foreground", rank: 0 },
    [MilestoneSeverity.Medium]: { Icon: WarningCircleIcon, text: "text-warning-soft-foreground", rank: 1 },
    [MilestoneSeverity.Low]: { Icon: InfoIcon, text: "text-muted", rank: 2 },
}

/** Render up to this many attempt buttons inline; beyond it, show the newest few + a "+N" overflow. */
const ATTEMPT_CHIPS_MAX = 6
/** When overflowing, how many newest buttons stay visible. */
const ATTEMPT_CHIPS_VISIBLE = 5

/** Props for {@link FindingAccordionItem}. */
interface FindingAccordionItemProps {
    /** The graded finding to render. */
    feedback: UserMilestoneTaskAttemptFeedbackEntity
    /** Optional repo URL used to deep-link the finding's file location. */
    repositoryUrl?: string
}

/**
 * One finding as an accordion item: header = severity icon + (clamped) message +
 * file location; expanding reveals the linked file location and the suggested fix.
 * Personal-project feedback has no `detail` field, so the panel is location +
 * suggestion only.
 *
 * @param props - the finding + the repo URL used to deep-link its file location.
 */
const FindingAccordionItem = ({
    feedback,
    repositoryUrl,
}: FindingAccordionItemProps) => {
    const visual = SEVERITY_VISUAL[feedback.severity] ?? SEVERITY_VISUAL[MilestoneSeverity.Medium]
    const { Icon } = visual
    const locationHref = feedback.location && repositoryUrl
        ? `${repositoryUrl.replace(/\.git$/, "")}/blob/HEAD/${feedback.location.replace(/^\//, "")}`
        : undefined

    return (
        <Accordion.Item id={feedback.id} aria-label={feedback.message}>
            <Accordion.Heading>
                <Accordion.Trigger className="w-full">
                    <div className="flex w-full items-center gap-3 text-start">
                        <Icon aria-hidden focusable="false" className={cn("size-4 shrink-0", visual.text)} />
                        <FillAvailable
                            at="base"
                            explain="Feedback title takes remaining trigger width beside severity icon and optional location chip so the message truncates instead of shoving peers."
                            body={() => (
                                <MarkdownContent
                                    markdown={feedback.message}
                                    density="compact"
                                    flow="embedded"
                                    previewLines={1}
                                />
                            )}
                        />
                        {feedback.location ? (
                            <Chip size="sm" className="hidden max-w-[34%] shrink-0 @app-sm:inline-flex">
                                <Chip.Label className="truncate">{feedback.location}</Chip.Label>
                            </Chip>
                        ) : null}
                        <Accordion.Indicator />
                    </div>
                </Accordion.Trigger>
            </Accordion.Heading>
            <Accordion.Panel>
                <Accordion.Body>
                    <div className="flex flex-col gap-2">
                        {feedback.location ? (
                            <div className="flex items-center gap-2 text-xs text-muted">
                                <MapPinIcon aria-hidden focusable="false" className="size-4 shrink-0" />
                                {locationHref ? (
                                    <Link href={locationHref} target="_blank" rel="noopener noreferrer" className="hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]">
                                        {feedback.location}
                                    </Link>
                                ) : (
                                    <span>{feedback.location}</span>
                                )}
                            </div>
                        ) : null}
                        {feedback.suggestion ? (
                            <div className="flex items-start gap-2">
                                <LightbulbIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />
                                <MarkdownContent
                                    markdown={feedback.suggestion}
                                    density="compact"
                                    tone="muted"
                                    flow="embedded"
                                />
                            </div>
                        ) : null}
                    </div>
                </Accordion.Body>
            </Accordion.Panel>
        </Accordion.Item>
    )
}

/**
 * Personal-project task result page (quality-gate report) ΓÇö mirrors the challenge
 * `SubmissionResult`. PageHeader (back to the task + task title) ΓåÆ attempt selector
 * (`FlexWrapButtonRadio` + history drawer) ΓåÆ two {@link LabeledCard}s: "Result"
 * (score hero + verdict from `attempt.passed` + the AI model that graded it) and
 * "Feedback" (findings accordion). Reads `?attempt=` (defaults newest); the selected
 * attempt drives the feedbacks query via redux `selectedAttemptId`.
 *
 * @param props - optional root className (placement only).
 */
export const PersonalProjectTaskResult = ({
    className,
}: PersonalProjectTaskResultProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const pathname = usePathname()
    const searchParams = useSearchParams()
    const dispatch = useAppDispatch()
    const [historyOpen, setHistoryOpen] = useState(false)
    // completion handoff (capstone track): after passing this task, hand off to the
    // NEXT unlocked milestone task. `currentTask` advances to the next task once this
    // one passes, so we show it only when it's a DIFFERENT task from the one just done.
    const courseId = useAppSelector((state) => state.course.id)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const milestoneProgressSwr = useQueryMilestoneTaskProgressSwr()
    const nextTaskId = milestoneProgressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id ?? null

    const attemptParam = searchParams.get("attempt")

    // hydrate the selected task detail (title / description / maxScore) into redux
    useQueryMilestoneTaskSwr()
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const maxScore = selectedTaskDetail?.maxScore ?? 0
    const githubUrl = usePersonalProjectGithubStore((state) => state.githubUrl)

    const attemptsSwr = useQueryUserPersonalTaskAttemptsSwr()
    const attempts = useMemo<Array<UserMilestoneTaskAttemptEntity>>(
        () => attemptsSwr.data?.data ?? [],
        [attemptsSwr.data],
    )
    // newest attempt is first (attemptNumber DESC); honour `?attempt=` when present
    const selectedAttempt = useMemo(
        () => (attemptParam ? attempts.find((attempt) => attempt.id === attemptParam) : undefined) ?? attempts[0],
        [attempts, attemptParam],
    )

    // the feedbacks hook is gated on redux `selectedAttemptId` ΓÇö keep it in sync
    useEffect(() => {
        dispatch(setSelectedAttemptId(selectedAttempt?.id))
    }, [dispatch, selectedAttempt?.id])

    const feedbacksSwr = useQueryUserPersonalTaskAttemptFeedbacksSwr()
    const feedbacks = useMemo<Array<UserMilestoneTaskAttemptFeedbackEntity>>(
        () => feedbacksSwr.data?.data ?? [],
        [feedbacksSwr.data],
    )

    // model catalog ΓåÆ map every served model id to its cost/quality tier (chip)
    const aiModelsSwr = useQueryAiModelsSwr()
    const modelCategoryMap = useMemo(() => {
        const map = new Map<string, AiModelCategory>()
        for (const model of aiModelsSwr.data?.aiModels?.data?.gradableModels ?? []) {
            map.set(model.model, model.category)
        }
        return map
    }, [aiModelsSwr.data])
    const servedCategory = selectedAttempt?.servedModel ? modelCategoryMap.get(selectedAttempt.servedModel) : undefined

    // findings sorted by severity (high ΓåÆ low), then by their stored order
    const sortedFeedbacks = useMemo(
        () => [...feedbacks].sort((a, b) => {
            const rankDiff = (SEVERITY_VISUAL[a.severity]?.rank ?? 1) - (SEVERITY_VISUAL[b.severity]?.rank ?? 1)
            return rankDiff !== 0 ? rankDiff : (a.sortIndex ?? 0) - (b.sortIndex ?? 0)
        }),
        [feedbacks],
    )

    // query auto-built from the top-severity findings' own text ΓÇö no typing. Only
    // meaningful on a FAILED attempt (a pass has nothing to "go fix"); the passing
    // case keeps its existing UpNextCard handoff instead.
    const failingFindingsQuery = useMemo(
        () => sortedFeedbacks.slice(0, 3).map((feedback) => feedback.message).join(" "),
        [sortedFeedbacks],
    )

    // selector: render up to ATTEMPT_CHIPS_MAX; beyond that show the newest few + "+N"
    const isOverflow = attempts.length > ATTEMPT_CHIPS_MAX
    const visibleAttempts = isOverflow ? attempts.slice(0, ATTEMPT_CHIPS_VISIBLE) : attempts
    const overflowCount = attempts.length - visibleAttempts.length

    /** Back to the task page (strip the trailing /result). */
    const taskHref = pathname.replace(/\/result\/?$/, "")
    /** URL that selects a given attempt on this result page. */
    const attemptHref = (id: string) => `${pathname}?attempt=${id}`

    const scoreLabel = (score: number | null) => (maxScore > 0 ? `${score ?? 0}/${maxScore}` : `${score ?? 0}`)

    const attemptsLoading = attemptsSwr.data === null || attemptsSwr.data === undefined ? !attemptsSwr.error : false
    const feedbacksLoading = feedbacksSwr.data === null || feedbacksSwr.data === undefined ? !feedbacksSwr.error : false

    const passing = selectedAttempt?.passed ?? false
    const timeAgo = selectedAttempt?.processedAt
        ? getTimeAgoLabel(getTimeAgoMessage(dayjs(selectedAttempt.processedAt)), t)
        : null

    return (
        // PageHeader (header) ΓåÆ content cluster, gap-10. No p-6 here ΓÇö the learn
        // shell already pads the PP content column (unlike the full-bleed challenge layout).
        <div className={cn("mx-auto flex w-full max-w-5xl flex-col gap-10", className)}>
            <PageHeader
                breadcrumb={(
                    <BackLink
                        label={t("personalProjectResult.backToTask")}
                        onPress={() => router.push(taskHref)}
                    />
                )}
                title={selectedTaskDetail?.title ?? t("personalProjectResult.title")}
                description={selectedTaskDetail?.description || undefined}
            />

            <div className="flex flex-col gap-6">
                {/* attempt buttons (newest few) that wrap; a "+N" button opens the full history drawer */}
                <AsyncContent
                    isLoading={attemptsLoading}
                    skeleton={(
                        <div className="flex gap-2">
                            {[0, 1].map((row) => (
                                <Skeleton key={row} className="h-9 w-32 rounded-full" />
                            ))}
                        </div>
                    )}
                    isEmpty={attempts.length === 0}
                    emptyContent={{
                        title: t("personalProjectResult.emptyAttempts"),
                        description: t("personalProjectResult.emptyAttemptsHint"),
                    }}
                    error={!attemptsSwr.data ? attemptsSwr.error : undefined}
                    errorContent={{
                        title: t("personalProjectResult.error"),
                        onRetry: () => { void attemptsSwr.mutate() },
                        retryLabel: t("personalProjectResult.retry"),
                    }}
                >
                    <div className="flex flex-col gap-3">
                        <Label>{t("personalProjectResult.attempts")}</Label>
                        <FlexWrapButtonRadio
                            ariaLabel={t("personalProjectResult.history")}
                            value={selectedAttempt?.id ?? ""}
                            onChange={(id) => router.push(attemptHref(id))}
                            items={visibleAttempts.map((attempt) => ({
                                value: attempt.id,
                                content: (
                                    <>
                                        <VerdictIcon pass={attempt.passed} />
                                        <span>{t("submissionAttempts.attemptLine", { number: attempt.attemptNumber })}</span>
                                        <span className="text-xs opacity-70">{scoreLabel(attempt.score)}</span>
                                    </>
                                ),
                            }))}
                            trailing={overflowCount > 0 ? (
                                <Button
                                    variant="tertiary"
                                    size="sm"
                                    aria-label={t("personalProjectResult.history")}
                                    onPress={() => setHistoryOpen(true)}
                                >
                                    {`+${overflowCount}`}
                                </Button>
                            ) : undefined}
                        />
                    </div>
                </AsyncContent>

                {/* selected attempt detail ΓÇö two labeled cards: "Result" + "Feedback" */}
                {selectedAttempt ? (
                    <div className="flex flex-col gap-6">
                        <SurfaceCard label={t("personalProjectResult.resultLabel")}
                            body={() => (
                                <StackV
                                    gap={3}
                                    principle="sibling-stack"
                                    explain="Score hero and model byline are peer result sections ΓÇö not block-boundary."
                                    items={[
                                        () => (
                                            <div className="flex items-start gap-3">
                                                <Score current={selectedAttempt.score ?? 0} max={maxScore} />
                                                <div className="min-w-0 flex-1">
                                                    <Chip color={passing ? "success" : "danger"} variant="soft" size="sm">
                                                        <VerdictIcon pass={passing} />
                                                        <Chip.Label>
                                                            {t(passing ? "personalProjectResult.passed" : "personalProjectResult.failed")}
                                                        </Chip.Label>
                                                    </Chip>
                                                    {selectedAttempt.shortFeedback ? (
                                                        <Typography type="body-sm" color="muted" className="mt-1">
                                                            {selectedAttempt.shortFeedback}
                                                        </Typography>
                                                    ) : null}
                                                </div>
                                                {githubUrl ? (
                                                    <Link
                                                        href={githubUrl}
                                                        target="_blank"
                                                        rel="noopener noreferrer"
                                                        className="flex shrink-0 items-center gap-2 text-sm text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                                                    >
                                                        {t("personalProjectResult.viewRepo")}
                                                        <ArrowSquareOutIcon aria-hidden focusable="false" className="size-5" />
                                                    </Link>
                                                ) : null}
                                            </div>
                                        ),
                                        () => (
                                            <div className="flex flex-wrap items-center gap-2 border-t border-default pt-3">
                                                <ModelByline model={selectedAttempt.servedModel} category={servedCategory} withLabel />
                                                {timeAgo ? (
                                                    <Typography type="body-xs" color="muted" className="ml-auto">
                                                        {timeAgo}
                                                    </Typography>
                                                ) : null}
                                            </div>
                                        ),
                                    ]}
                                />
                            )}
                        />

                        {/* findings ΓÇö a labeled accordion card (each finding expands). frameless
                            ONLY once the accordion self-frames; loading/empty/erroring have no
                            bounded surface of their own, so LabeledCard's Card must frame them. */}
                        <LabeledCard
                            label={t("personalProjectResult.feedbackLabel")}
                            frameless={!feedbacksLoading && !(!feedbacksSwr.data && feedbacksSwr.error) && feedbacks.length > 0}
                        >
                            <AsyncContent
                                isLoading={feedbacksLoading}
                                skeleton={<Skeleton className="h-40 w-full rounded-2xl" />}
                                isEmpty={feedbacks.length === 0}
                                emptyContent={{ title: t("personalProjectResult.noFeedback") }}
                                error={!feedbacksSwr.data ? feedbacksSwr.error : undefined}
                                errorContent={{
                                    title: t("personalProjectResult.error"),
                                    onRetry: () => { void feedbacksSwr.mutate() },
                                    retryLabel: t("personalProjectResult.retry"),
                                }}
                            >
                                {/* Accordion Card: the surface accordion IS the card (frameless
                                    label outside, p-0) ΓÇö surface bakes bg + radius + separators. */}
                                <Accordion
                                    variant="surface"
                                    className="overflow-hidden shadow-surface"
                                    allowsMultipleExpanded
                                >
                                    {sortedFeedbacks.map((feedback) => (
                                        <FindingAccordionItem
                                            key={feedback.id}
                                            feedback={feedback}
                                            repositoryUrl={githubUrl || undefined}
                                        />
                                    ))}
                                </Accordion>
                            </AsyncContent>
                        </LabeledCard>

                        {/* quiet, self-hiding "what to read to fix this" ΓÇö ONLY when the attempt
                            failed (a pass has nothing to go fix; that case keeps its existing
                            UpNextCard handoff below instead). Query auto-built from the findings
                            themselves, no typing. */}
                        {!passing && courseId && courseDisplayId ? (
                            <RelatedContentList
                                courseId={courseId}
                                courseDisplayId={courseDisplayId}
                                query={failingFindingsQuery}
                                excludeId={selectedTaskId ?? undefined}
                                label={t("personalProjectResult.relatedContent.label")}
                            />
                        ) : null}
                    </div>
                ) : null}
                {/* capstone-track handoff: passed ΓåÆ next milestone task */}
                {passing && nextTaskId && nextTaskId !== selectedTaskId && courseDisplayId ? (
                    <UpNextCard
                        showCheck
                        eyebrow={t("personalProjectResult.upNextEyebrow")}
                        title={t("personalProjectResult.nextTaskTitle")}
                        description={t("personalProjectResult.nextTaskDesc")}
                        ctaLabel={t("personalProjectResult.nextTaskCta")}
                        onPress={() => router.push(
                            pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(nextTaskId).build(),
                        )}
                    />
                ) : null}
            </div>

            <PersonalProjectTaskResultHistoryDrawer
                isOpen={historyOpen}
                onOpenChange={setHistoryOpen}
                attempts={attempts}
                selectedAttemptId={selectedAttempt?.id}
                maxScore={maxScore}
                modelCategoryMap={modelCategoryMap}
                onSelect={(id) => router.push(attemptHref(id))}
            />
        </div>
    )
}

export default PersonalProjectTaskResult

/** Folder-matching alias (export-matches-folder) ΓÇö keep `PersonalProjectTaskResult` as the public name. */
export { PersonalProjectTaskResult as TaskResult }

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { SkeletonText } from "@/components/blocks/skeleton/SkeletonText"
import { SkeletonParagraph } from "@/components/blocks/skeleton/SkeletonParagraph"

/** Props for {@link TaskSkeleton}. */
export type TaskSkeletonProps = WithClassNames<undefined>

/**
 * Loading placeholder for the milestone task BRIEF column
 * ({@link import("../").Task}).
 *
 * Mirrors the real layout 1:1 so nothing jumps when the task lands: the
 * `gap-6` stack of the tier-2 header (H3 title `text-2xl` + `body-sm` description,
 * a tight pair) followed by the per-language brief card. Static-shaped, no logic.
 * @param props - optional className for the root element
 */
export const TaskSkeleton = ({
    className,
}: TaskSkeletonProps = {}) => {
    return (
        <div className={cn("flex flex-col gap-6", className)}>
            {/* tier-2 header ΓÇö title (H3) + description, the gap-0 pair */}
            <div className="flex flex-col gap-2">
                <SkeletonText size="2xl" width="w-2/3" />
                <SkeletonParagraph size="sm" lines={2} />
            </div>
            {/* per-language brief card */}
            <Skeleton className="h-[220px] w-full rounded-xl" />
        </div>
    )
}
